import {categories,surfaces,colors,layerNames,sourceRows} from './data.mjs';
import {initialState,allProducts,addCustomerProduct,deleteCustomerProduct,selectProduct,customLaborOptions,addCustomerLaborOption,selectLaborOption,deleteCustomerLaborOption,customMaintenanceLaborOptions,addCustomerMaintenanceLaborOption,selectMaintenanceLaborOption,deleteCustomerMaintenanceLaborOption,has,val,num,area,edge,category,categoryCoverage,calculate,comparison,adjusted,exportRows,toCSV,safeDiv} from './engine.mjs';
let state=initialState(),registry=new Map(),invalidKeys=new Set(),fieldCount=0,printing=false;
const app=document.querySelector('#app');
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(x,d=2)=>Number(x).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const money=(x,d=2)=>invalidKeys.size?'—':'$'+fmt(x,d);
const range=(r,d=2)=>invalidKeys.size?'—':`${money(r[0],d)} – ${money(r[1],d)}`;
const modes=()=>state.labor==='both'?['ih','out']:[state.labor];
const modeName=m=>m==='ih'?'In-house crew':'Outsourced (contractor)';
const activeId=()=>state.surface;
const icons={leaf:'<path d="M20 4c-8-1-15 2-15 9a6 6 0 0 0 6 6c7 0 9-7 9-15Z"/><path d="m4 21 11-11"/>',layers:'<path d="m12 3 10 6-10 6L2 9l10-6Zm-10 12 10 6 10-6M2 12l10 6 10-6"/>',mountain:'<path d="m2 20 7-14 4 7 3-5 6 12H2Z"/><path d="m6 12 3 2 3-2"/>',road:'<path d="M7 3 3 21M17 3l4 18M12 3v4m0 4v3m0 4v3"/>',grid:'<rect x="3" y="3" width="18" height="18" rx="1"/><path d="M3 12h18M12 3v18"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.layers}</svg>`;
function field(key,label,def,opt={}){opt={...opt,required:opt.required||(!opt.text&&opt.min>0&&def!=null)};registry.set(key,{def,...opt});const edited=has(state,key),v=val(state,key,def),displayValue=typeof v==='number'&&!edited?Number(v.toFixed(4)):v,uid=`f${fieldCount++}`;return `<div class="field ${edited?'edited':''} ${invalidKeys.has(key)?'invalid':''}">${label?`<label for="${uid}">${e(label)}</label>`:''}<div class="fieldbox"><input id="${uid}" data-key="${e(key)}" aria-label="${e(label||opt.aria||key)}" ${invalidKeys.has(key)?'aria-invalid="true"':''} type="${opt.text?'text':'number'}" ${!opt.text?`step="any" min="${opt.min??0}" ${opt.max!==undefined?`max="${opt.max}"`:''}`:''} value="${e(displayValue??'')}" placeholder="${e(opt.placeholder??(def==null?'Not entered':def))}" ${opt.required?'required':''}>${opt.suffix?`<span class="suffix">${e(opt.suffix)}</span>`:''}</div><div class="fieldmeta">${edited?`<span class="badge">edited</span><button class="reset" data-reset="${e(key)}" aria-label="Reset ${e(label||opt.aria||key)} to default">↺ reset to default</button>`:''}</div></div>`;}
function details(id,title,body,open=false){return `<details data-panel="${e(id)}" ${open?'open':''}><summary>${title}</summary><div class="detail-body">${body}</div></details>`;}
const heading=(n,title,text)=>`<div class="heading"><div><p class="eyebrow">${n}</p><h2>${title}</h2><p class="lede">${text}</p></div><span class="tag">Texas · July 2026</span></div>`;
function resultCards(r,title,adjust=true){return `<div class="result-grid">${modes().map(m=>`<div class="result-card ${m==='out'?'out':''}"><div class="label">${title} · ${modeName(m)}</div><div class="large-range">${range(r[m])}</div><small>Low – High estimate · USD</small>${adjust?`<div class="adjusted"><span>With estimate adjustment (${num(state,'adj.low',-15)}% / +${num(state,'adj.high',15)}%)</span><strong>${range(adjusted(state,r[m]))}</strong></div>`:''}</div>`).join('')}</div>`;}
function diagram(c){let y=55;const layerList=[...c.layers.filter(x=>x.layer==='treatment'),...c.layers.filter(x=>x.layer==='surface'||x.layer==='base')];let surfaceY=55,surfaceH=60;let shapes='';for(const x of layerList){const h=x.layer==='treatment'?16:x.layer==='base'?45:c.id==='concrete'?78:58;if(x.layer==='surface'){surfaceY=y;surfaceH=h;}const labelY=x.layer==='surface'&&c.id==='concrete'?y+20:y+h/2;shapes+=`<rect x="35" y="${y}" width="280" height="${h}" fill="${colors[x.layer]}"/><path d="M319 ${labelY}h28" stroke="#89917f"/><text x="360" y="${labelY+4}">${e(layerNames[x.layer])}</text>`;y+=h+3;}if(c.layers.some(x=>x.layer==='reinforcement')){const ry=surfaceY+surfaceH*.7;shapes+=`<path d="M39 ${ry}h272" stroke="${colors.reinforcement}" stroke-width="5" stroke-dasharray="7 3"/><path d="M319 ${ry}h28" stroke="#89917f"/><text x="360" y="${ry+4}">Embedded steel remesh</text>`;}const fabric=c.layers.some(x=>x.layer==='fabric'),edging=c.layers.some(x=>x.layer==='edge');return `<div class="diagram-wrap"><svg class="diagram" viewBox="0 0 590 260" role="img" aria-label="Schematic cross-section for ${e(c.surface.name)}"><text x="35" y="27">${e(c.surface.name.toUpperCase())}</text>${shapes}${fabric?`<path d="M35 ${y+4}h280" stroke="${colors.fabric}" stroke-width="4" stroke-dasharray="10 5"/><path d="M320 ${y+4}h27" stroke="#89917f"/><text x="360" y="${y+9}">Geotextile / fabric</text>`:''}${edging?`<rect x="26" y="51" width="9" height="${y-46}" fill="${colors.edge}"/><rect x="315" y="51" width="9" height="${y-46}" fill="${colors.edge}"/><text class="subtext" x="35" y="246">Edging contains both sides of the trail.</text>`:''}<path d="M35 ${y+21}h280" stroke="#b7bead"/><text class="subtext" x="35" y="${y+40}">Prepared ground</text></svg><div class="diagram-footer">Layer schematic · not to scale</div></div>`;}
function originalHeader(c){const sc=c.scenarios[state.summaryScenario];return `<header class="masthead"><div class="shell"><div class="brandrow"><div class="brand"><div class="brandmark">${icon('layers')}</div><div><h1>Feasibility Toolbox</h1><p>RURAL PARK & TRAIL PLANNING TOOLKIT</p></div></div><div class="toplinks"><span class="edition">Toolbox 01</span><button class="text" data-step="overview" ${state.step==='overview'?'aria-current="page"':''}>Overview</button><button class="text" data-step="methods" ${state.step==='methods'?'aria-current="page"':''}>Methods & sources</button></div></div></div></header><nav class="stepbar" aria-label="Calculator steps"><div class="shell steps">${[['construction','Construction'],['maintenance','Maintenance & Operations'],['lifecycle','Replacement & Lifecycle']].map(([id,label],i)=>`<button class="step ${state.step===id?'active':''}" data-step="${id}" ${state.step===id?'aria-current="step"':''}><span class="stepnum">${i+1}</span><span>${label}</span></button>`).join('')}</div></nav><div class="shell"><section class="project" aria-label="Project inputs"><p class="sectionlabel">Choose your trail surface</p><div class="surface-grid">${Object.entries(surfaces).map(([id,s])=>`<button class="surface ${state.surface===id?'selected':''}" data-surface="${id}" aria-pressed="${state.surface===id}">${icon(s.icon)}<span><strong>${e(s.name)}</strong><span class="sub">${e(s.description)}</span></span></button>`).join('')}</div><div class="project-row"><div class="inputs-row">${field('area','Trail area',num(state,'length',0)>0&&num(state,'width',0)>0?num(state,'length',0)*num(state,'width',0):20000,{suffix:'sq. ft.',min:.000001,required:true})}${field('length','Length (optional)',null,{suffix:'ft'})}${field('width','Width (optional)',null,{suffix:'ft'})}${field('edge','Edge length',num(state,'length',0)>0?2*num(state,'length',0):null,{suffix:'lin. ft.'})}</div><div class="labor-control"><p class="sectionlabel" style="margin-bottom:7px">Labor comparison</p><div class="segmented" aria-label="Labor display">${[['ih','In-house'],['out','Outsourced'],['both','Show both']].map(([id,l])=>`<button data-labor="${id}" class="${state.labor===id?'selected':''}" aria-pressed="${state.labor===id}">${l}</button>`).join('')}</div></div></div><p class="hint">Length × width supplies the area; 2 × length supplies edging. A direct override takes precedence. Grey fields are defaults; yellow fields are your edits.</p></section></div><aside class="mini-summary" aria-label="Project summary"><div class="shell"><div class="mini-inner"><div><label for="summary-scenario">${e(c.surface.short)} · ${fmt(c.A,0)} sq. ft.</label><select id="summary-scenario" aria-label="Scenario for summary"><option value="0" ${state.summaryScenario===0?'selected':''}>Scenario 1 · Maintain</option><option value="1" ${state.summaryScenario===1?'selected':''}>Scenario 2 · Rebuild</option></select></div>${[['Construction',c.construction],['Maintenance / year',sc.annual],['Lifecycle · '+c.C+' years',sc.total]].map(([label,r])=>`<div class="mini-stat"><span>${label}</span>${modes().map(m=>`<strong>${range(r[m],0)}</strong><small>${m==='ih'?'In-house':'Outsourced'}</small>`).join('')}</div>`).join('')}</div></div></aside>`;}
function originalOverview(c){return `<div class="overview-grid"><div class="intro"><p class="eyebrow">Plan the whole life of your trail</p><h2>Can we afford to build it<br>and keep it?</h2><p>A shared starting point for rural communities, park boards, and city councils. Turn your trail size and surface choice into a budget for construction, upkeep, and replacement.</p><button class="primary" data-step="construction">Start → Step 1</button><div class="lens-grid">${[['01','Construct','One moment.'],['02','Maintain','Every year.'],['03','Replace','Comes around again.']].map(x=>`<div class="lens"><span class="number">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div></div><div class="overview-panel"><div><p class="sectionlabel">Your starting estimate · ${e(c.surface.short)}</p><h3>${fmt(c.A,0)} square feet. A full-cycle view.</h3><p class="small-note">Scenario 1 · ${c.C} years · ${state.labor==='out'?'Outsourced':'In-house crew'}</p><div class="large-range">${range(c.scenarios[0].total[state.labor==='out'?'out':'ih'])}</div><p class="small-note">Construction + cycle-long maintenance.<br>No end-of-cycle rebuild at the default 100% maintained.</p></div>${diagram(c)}<p class="small-note">The cheapest trail to build is rarely the cheapest to own.</p></div></div><div class="purpose-grid">${[['Estimate first cost','Build a construction budget from material quantities and labor rates.'],['Plan for upkeep','Translate routine tasks and visits into an annual maintenance budget.'],['Anticipate replacement','Plan for resurfacing, removal, and a complete rebuild.'],['Compare fairly','Compare both full-cycle costs and average cost per year.']].map(([h,p])=>`<div class="purpose"><h3>${h}</h3><p>${p}</p></div>`).join('')}</div><div class="risks"><h3>Avoid budget surprises</h3><ul><li>Building a trail you cannot afford to maintain.</li><li>Resurfacing bills without a reserve.</li><li>A surface that fails in Texas heat and rain.</li><li>Choosing on construction price alone.</li></ul></div>`;}
function customerProductForm(key){const c=categories[key];return `<div class="customer-product-tools"><h4>Your product choices</h4><p>Add a product for ${e(c.name)} or select example products below. New products appear in this category under Full product lists &amp; editable defaults.</p>${details('add-product-'+key,'+ Add your product',`<form data-add-product="${key}"><p class="small-note">All fields marked * are required. Adding this product selects it alone for this category; check other products below if you want to average them. Entries stay in this page session; export the CSV before closing.</p><div class="controls-grid"><label>Product / brand name *<input name="name" required maxlength="200" placeholder="Enter product and brand"></label><label>Added by (your name) *<input name="contributor" required maxlength="120" placeholder="Enter your name"></label><label>Package price ($) *<input name="listed" type="number" min="0.000001" step="any" required placeholder="Total package price"></label><label>Quantity in package (${e(c.purchase)}) *<input name="pack" type="number" min="0.000001" step="any" required placeholder="Number of purchase units"></label><label>Coverage per 1 ${e(c.purchase)} (${e(c.unit)}) *<input name="coverage" type="number" min="0.000001" step="any" required placeholder="Area or length covered per unit"></label><label>Supplier / quote reference (optional)<input name="source" maxlength="300" placeholder="Supplier or quote reference"></label></div><p class="small-note">Price per ${e(c.purchase)} = package price ÷ package quantity. Cost per ${e(c.unit)} = that price ÷ coverage per ${e(c.purchase)}. Use coverage at the design thickness shown below.</p><p class="product-form-error" role="alert"></p><button type="submit" class="primary">Add product &amp; use its price</button></form>`)}</div>`;}
function productEditor(key,context=''){const c=category(state,key);return `${customerProductForm(key)}<p class="small-note">${e(c.name)} · ${c.products.length} available products · ${c.selectedCount} selected. Only checked products contribute to the unweighted average. Adding a product or changing a selection clears category and related activity material-price overrides so the selected prices are used.</p><div class="controls-grid">${c.depth?field(`cat.${key}.depth`,'Design thickness',c.depth,{suffix:'in.',min:.000001}):field(`cat.${key}.thickness`,'Thickness / application label',c.thickness,{text:true})}${field(`cat.${key}.coverage`,'Coverage per purchase unit',categoryCoverage({...state,overrides:Object.fromEntries(Object.entries(state.overrides).filter(([k])=>k!==`cat.${key}.coverage`))},key),{suffix:c.unit,min:.000001})}${field(`cat.${key}.cost`,'Category price override',c.average,{suffix:'$/'+c.unit})}</div>${key==='ASPH_SURF'?`<div class="controls-grid">${field('asphalt.density','Density convention',110,{suffix:'lb/SY/in.',min:.000001})}${field('asphalt.tonWeight','Pounds per ton',2000,{min:.000001})}${field('asphalt.sqyd','Square feet per square yard',9,{min:.000001})}${field('asphalt.baseDepth','Aggregate base depth',6,{suffix:'in.'})}</div><p class="small-note">The supplied construction schedule has no separate aggregate-base cost line. This model retains that schedule.</p>`:''}${key==='ASPH_TREAT'?`<div class="controls-grid">${field('asphalt.sealerArea','Coverage per pail',300,{suffix:'sq. ft.',min:.000001})}${field('asphalt.sealerPail','Pail volume',4.75,{suffix:'gal',min:.000001})}</div>`:''}<div class="table-scroll"><table><thead><tr><th>Include in average / product</th><th>Listed package price / size</th><th>Cost / purchase unit</th><th>Coverage / purchase unit</th><th class="numeric">Cost / estimating unit</th></tr></thead><tbody>${c.products.map((p,i)=>({p,i})).sort((a,b)=>Number(!!b.p.custom)-Number(!!a.p.custom)).map(({p,i})=>{const pre=`prod.${key}.${i}`,base=allProducts(state,key)[i];return `<tr class="${p.selected?'product-included':'product-excluded'}"><td><label class="product-choice"><input type="checkbox" data-product-select="${key}" data-index="${i}" ${p.selected?'checked':''} aria-label="Include ${e(p.name)} in average"><span>Include in average</span></label>${field(`${pre}.name`,'Product name',base.name,{text:true,required:true})}<div class="small-note">${p.custom?'Customer product · Added by '+e(p.contributor)+'<br>':'Example product<br>'}${e(p.source)}</div>${p.custom?`<button type="button" class="delete-product small" data-delete-product="${key}" data-index="${i}" aria-label="Delete ${e(p.name)}">Delete product</button>`:''}</td><td>${p.listed!==null?`${field(`${pre}.listed`,'Listed price',base.listed,{suffix:'$'})}${field(`${pre}.pack`,'Package quantity',base.pack,{min:.000001})}`:'<span class="small-note">Published as a unit price</span>'}</td><td>${field(`${pre}.price`,'Purchase-unit price',p.autoPrice,{suffix:'$'})}</td><td>${field(`${pre}.coverage`,'Coverage',base.coverage??c.coverage,{min:.000001,suffix:c.unit})}</td><td class="numeric">${money(p.cost,4)}<br><small>/ ${e(c.unit)}</small></td></tr>`;}).join('')}</tbody><tfoot><tr class="subtotal"><td colspan="4">Selected product average · ${c.selectedCount} product${c.selectedCount===1?'':'s'}</td><td class="numeric">${money(c.average,4)}</td></tr></tfoot></table></div><p class="small-note">The supplied purchase-unit prices are the default inputs. Listed package prices are source references until edited; editing a listed price or package quantity recalculates its purchase-unit price. Direct price or coverage overrides take precedence.</p>`;}
function adjustments(){return details('adjustment','Estimate adjustment · applies to every cost category',`<div class="controls-grid">${field('adj.low','Low estimate adjustment',-15,{suffix:'%',min:-100})}${field('adj.high','High estimate adjustment',15,{suffix:'%',min:-100})}</div><p class="small-note">Adjusted low = low × (1 + low adjustment). Adjusted high = high × (1 + high adjustment). Unadjusted ranges remain visible.</p>`);}
function customerLaborForm(c){return `<div class="customer-labor-tools"><h4>Add a labor option</h4><p>Enter a local crew or contractor estimate for ${e(c.surface.name)}. The new option is selected automatically for its labor type.</p>${details('add-labor-'+c.id,'+ Add labor option',`<form data-add-labor="${c.id}"><p class="small-note">All fields are required. Use a fully loaded hourly billing rate for an outsourced contractor when appropriate. Entries stay in this page session; export the CSV before closing.</p><div class="controls-grid"><label>Labor option *<select name="mode" required><option value="ih">In-house</option><option value="out">Outsourced</option></select></label><label>Crew or contractor name *<input name="name" required maxlength="200" placeholder="e.g., Parks maintenance crew"></label><label>Added by (your name) *<input name="contributor" required maxlength="120" placeholder="Enter your name"></label><label>Hourly labor rate · Low *<span class="form-input-with-suffix"><input name="lowHourly" type="number" min="0.000001" step="any" required placeholder="Low estimate"><span>$/worker-hour</span></span></label><label>Hourly labor rate · High *<span class="form-input-with-suffix"><input name="highHourly" type="number" min="0.000001" step="any" required placeholder="High estimate"><span>$/worker-hour</span></span></label><label>Area one worker completes in one hour *<span class="form-input-with-suffix"><input name="sqftPerHour" type="number" min="0.000001" step="any" required placeholder="e.g., 62.5"><span>sq. ft./worker-hour</span></span></label></div><div class="labor-formula"><span>Hourly labor rate</span><b>÷</b><span>Area completed per worker-hour</span><b>=</b><span>Construction labor rate per sq. ft.</span></div><p class="product-form-error" role="alert"></p><button type="submit" class="primary">Add and use labor option</button></form>`)}</div>`;}
function laborOptionRows(c,mode){const selected=state.laborSelections?.[c.id]?.[mode]??'default',custom=customLaborOptions(state,c.id,mode),base=c.surface[mode],reference=[num(state,c.id+'.construction.'+mode+'.low',base[0]),num(state,c.id+'.construction.'+mode+'.high',base[1])];return `<tr class="${selected==='default'?'labor-selected':''}"><td><label class="labor-choice"><input type="radio" name="labor-${c.id}-${mode}" data-labor-select="${c.id}" data-mode="${mode}" data-index="default" ${selected==='default'?'checked':''}><span><strong>${modeName(mode)}</strong><small>Supplied reference</small></span></label></td><td>${mode==='ih'?`<strong>${money(reference[0],2)}</strong><small class="calculation-note">Read-only reference rate</small>`:field(`${c.id}.construction.${mode}.low`,'Low rate',base[0],{suffix:'$/sq. ft.'})}</td><td>${mode==='ih'?`<strong>${money(reference[1],2)}</strong><small class="calculation-note">Read-only reference rate</small>`:field(`${c.id}.construction.${mode}.high`,'High rate',base[1],{suffix:'$/sq. ft.'})}</td><td class="numeric">${range(reference)}</td><td></td></tr>${custom.map((x,i)=>{const rates=[safeDiv(x.lowHourly,x.sqftPerHour),safeDiv(x.highHourly,x.sqftPerHour)],active=selected===i;return `<tr class="${active?'labor-selected':''}"><td><label class="labor-choice"><input type="radio" name="labor-${c.id}-${mode}" data-labor-select="${c.id}" data-mode="${mode}" data-index="${i}" ${active?'checked':''}><span><strong>${e(x.name)}</strong><small>${mode==='ih'?'In-house':'Outsourced'} · Added by ${e(x.contributor)}</small></span></label></td><td><strong>${money(rates[0],4)}</strong><small class="calculation-note">${money(x.lowHourly,2)}/hr ÷ ${fmt(x.sqftPerHour,2)} sq. ft./worker-hour</small></td><td><strong>${money(rates[1],4)}</strong><small class="calculation-note">${money(x.highHourly,2)}/hr ÷ ${fmt(x.sqftPerHour,2)} sq. ft./worker-hour</small></td><td class="numeric">${range(rates,4)}</td><td><button type="button" class="delete-product small" data-delete-labor="${c.id}" data-mode="${mode}" data-index="${i}" aria-label="Delete ${e(x.name)}">Delete</button></td></tr>`;}).join('')}`;}
function inHouseReference(c){const f=c.surface,h=f.ihHourly,prod=f.productivity,workerHours=f.referenceWorkers*8,unit=[safeDiv(h[0],prod),safeDiv(h[1],prod)];return `<section class="inhouse-reference" aria-label="Reference in-house crew calculation"><div class="inhouse-reference-head"><div><p class="sectionlabel">Reference calculation · ${e(f.short)}</p><h4>How the in-house crew rate is calculated</h4></div><span class="reference-status">Read-only default</span></div><div class="inhouse-reference-grid"><div><span>Published salary-schedule range</span><strong>${money(h[0],2)}–${money(h[1],2)}</strong><small>per worker-hour · ${e(f.wageClass)}</small></div><div><span>Planning productivity assumption</span><strong>${fmt(prod,2)} sq. ft.</strong><small>completed per worker-hour</small></div><div><span>Reference labor rate</span><strong>${money(f.ih[0],2)}–${money(f.ih[1],2)}</strong><small>per sq. ft. · used in the estimate</small></div></div><div class="reference-formula"><span>${money(h[0],2)}–${money(h[1],2)} / worker-hour</span><b>÷</b><span>${fmt(prod,2)} sq. ft. / worker-hour</span><b>=</b><span>≈ ${money(unit[0],2)}–${money(unit[1],2)} / sq. ft.</span></div><div class="reference-notes"><p><strong>Productivity basis:</strong> ${f.referenceWorkers} workers × 8 hours ÷ 1,000 sq. ft. = ${fmt(safeDiv(workerHours,1000),3)} worker-hours per sq. ft.</p><p><strong>Includes:</strong> base wages. <strong>Excludes:</strong> fringe benefits, equipment, and materials.</p><p><strong>Source and assumption:</strong> Hourly wages use the Texas State Auditor salary schedule. Productivity is a planning assumption, not an observed time study.</p></div></section>`;}
function constructionLaborEditor(c){return `${inHouseReference(c)}${customerLaborForm(c)}<p class="small-note"><strong>Choose one option for each labor type.</strong> The selected rate is used in construction, replacement labor, lifecycle totals, and exported results. To replace the read-only reference with local figures, add a labor option above.</p><div class="table-scroll"><table class="labor-options-table"><thead><tr><th>Use this labor option</th><th>Low rate · $/sq. ft.</th><th>High rate · $/sq. ft.</th><th class="numeric">Calculated rate · Low–High</th><th>Action</th></tr></thead><tbody>${laborOptionRows(c,'ih')}${laborOptionRows(c,'out')}</tbody></table></div><p class="note">Third-party estimates may already include some material cost. Confirm what a contractor's hourly billing rate includes before combining it with the separate material estimate.</p>`;}
function laborExplainer(){return `<div class="two-col"><div><h4>In-house · agency grounds crew</h4><p>Mulch example: <strong>$0.27–$0.40/sq. ft.</strong> Texas SAO Maintenance Specialist II, Class 9042, Salary Group A13.</p><p>$35,439–$52,388 per year ÷ 2,080 hours = $17.04–$25.19/hour. The crew completes 1,000 sq. ft. in 16 worker-hours, equal to 62.5 sq. ft. per worker-hour. Hourly rate ÷ area completed per worker-hour gives the unit labor cost.</p><p class="small-note">Base wages only; excludes fringe benefits, equipment, and materials. A13 covers routine journey-level maintenance, masonry, carpentry, and equipment operation. No licensed trade is assumed for fabric placement, mulch spreading, or compactor work.</p></div><div><h4>Outsourced · contractor crew</h4><p>Mulch example: <strong>$0.71–$1.38/sq. ft.</strong> Homewyse installed-cost calculator, run on Texas ZIP codes.</p><p>Labor cost = quantity × labor effort per unit × total labor wage. The Unit Cost Method uses U.S. Bureau of Labor Statistics wage data and a published low-to-high band.</p><p class="small-note">Includes contractor overhead, insurance, and benefits. Excludes general-contractor markup, permits, and sales tax. Texas SAO classification revised September 1, 2025.</p></div></div>`;}
function laborLibrary(){return `<section class="labor-library" aria-labelledby="labor-library-title"><div class="library-heading"><div><p class="sectionlabel">Editable labor library</p><h3 id="labor-library-title">Full labor lists &amp; editable defaults</h3></div><span class="reference-status">Construction + maintenance</span></div><p class="small-note">Review every supplied labor rate and any customer-added option in one place. Selecting or editing a rate updates the Cost Calculator immediately. Customer-added options can be deleted here or from their Cost Calculator activity.</p>${Object.keys(surfaces).map(id=>{const c=calculate(state,id),constructionCustom=customLaborOptions(state,id,'ih').length+customLaborOptions(state,id,'out').length,activities=c.scenarios[0].activities,maintenanceCustom=activities.reduce((n,a)=>n+customMaintenanceLaborOptions(state,id,a.id,'ih').length+customMaintenanceLaborOptions(state,id,a.id,'out').length,0);return details(`labor-library-${id}`,`${e(c.surface.name)} · ${constructionCustom+maintenanceCustom} customer-added option${constructionCustom+maintenanceCustom===1?'':'s'}`,`<div class="labor-library-section"><div class="panel-head"><div><p class="sectionlabel">Construction labor</p><h4>${e(c.surface.name)}</h4></div><a class="context-link" href="#construction/construction-labor" data-go="construction" data-target="construction-labor" data-use-surface="${id}">Add or manage in Cost Calculator</a></div>${inHouseReference(c)}<p class="small-note">Choose one supplied or customer-added option for each labor type. Delete is available only for customer-added options.</p><div class="table-scroll"><table class="labor-options-table"><thead><tr><th>Use this labor option</th><th>Low rate · $/sq. ft.</th><th>High rate · $/sq. ft.</th><th class="numeric">Calculated rate · Low–High</th><th>Action</th></tr></thead><tbody>${laborOptionRows(c,'ih')}${laborOptionRows(c,'out')}</tbody></table></div></div><div class="labor-library-section"><div class="panel-head"><div><p class="sectionlabel">Maintenance labor</p><h4>${activities.length} activities for ${e(c.surface.name)}</h4></div><a class="context-link" href="#maintenance/maintenance-inputs" data-go="maintenance" data-target="maintenance-inputs" data-use-surface="${id}">Add or manage in Cost Calculator</a></div><p class="small-note">Open an activity to inspect its source calculation, edit the supplied Low–High rates, select a customer-added option, or delete a customer-added option.</p>${activities.map(a=>details(`labor-library-${id}-${a.id}`,e(a.name),`${maintenanceReference(a)}<div class="table-scroll"><table class="labor-options-table"><thead><tr><th>Use this labor option</th><th>Low rate</th><th>High rate</th><th class="numeric">Calculated rate · Low–High</th><th>Action</th></tr></thead><tbody>${maintenanceLaborRows(c,a,'ih')}${maintenanceLaborRows(c,a,'out')}</tbody></table></div><p><a class="context-link" href="#maintenance/activity-${a.id}" data-go="maintenance" data-target="activity-${a.id}" data-use-surface="${id}">Open this activity in Cost Calculator</a></p>`)).join('')}</div>`)}).join('')}<p class="note"><strong>Session storage:</strong> customer-added labor options remain available while this page is open. Export the CSV before closing the page if you need a record of them.</p></section>`;}
function originalConstruction(c){return `${heading('Step 01 · Construction','What will it cost to build?','Choose the layers and quantities, then compare an agency crew with a contractor.')}<div class="two-col"><section class="panel"><div class="panel-head"><h3>Trail cross-section</h3><span class="pill">${e(c.surface.short)}</span></div>${diagram(c)}<p class="small-note">Standard thicknesses are planning defaults. Adjust them in the product details below.</p></section><section class="panel"><h3>Construction budget</h3><div class="statline"><span>Materials only</span><strong>${range([c.construction.material,c.construction.material])}</strong></div>${modes().map(m=>`<div class="statline"><span>${modeName(m)} · labor</span><strong>${range(c.construction.labor[m])}</strong></div>`).join('')}<div style="margin-top:20px">${resultCards(c.construction,'Materials + labor')}</div></section></div><section class="panel" id="construction-layers"><div class="panel-head"><h3>Construction layers</h3><span class="small-note">All unit prices can be edited</span></div><div class="legend"><span style="--swatch:#f1f2ee">Auto-filled default</span><span style="--swatch:#fff2bf">Your override</span></div><div class="table-scroll"><table><thead><tr><th>Layer / material</th><th>Standard thickness</th><th>Quantity</th><th>Unit price</th><th class="numeric">Material cost · Low – High</th></tr></thead><tbody>${c.layers.map(l=>`<tr><td><span class="layer-dot" style="background:${colors[l.layer]}"></span><strong>${e(layerNames[l.layer])}</strong><div class="small-note">${e(l.name)}</div></td><td>${e(l.thickness)}<div class="small-note">${e(l.unit)}</div></td><td>${field(`${c.id}.quantity.${l.key}`,'Layer quantity',l.defaultQuantity,{suffix:l.unit})}</td><td>${field(`cat.${l.key}.cost`,'Cost per unit',l.average,{suffix:'$'})}</td><td class="numeric">${range([l.total,l.total])}</td></tr>`).join('')}<tr class="total-row"><td colspan="4">Construction material subtotal</td><td class="numeric">${range([c.construction.material,c.construction.material])}</td></tr></tbody></table></div>${c.layers.map(l=>details(`construction-${l.key}`,`Show detail · ${e(l.name)}`,productEditor(l.key))).join('')}</section><section class="panel" id="construction-labor"><div class="panel-head"><div><h3>Construction labor</h3><p class="small-note">Rates apply to the whole trail area: ${fmt(c.A,0)} sq. ft.</p></div><span class="pill">${e(c.surface.short)}</span></div>${constructionLaborEditor(c)}</section>${adjustments()}<section class="panel" id="construction-time"><h3>How long will construction take?</h3><div class="controls-grid">${field(`${c.id}.productivity`,'Productivity',c.surface.productivity,{suffix:'sq. ft./hr',min:.000001})}${field('time.hoursDay','Hours per working day',8,{min:.000001})}${field('time.daysWeek','Working days per week',5,{min:.000001})}${field('time.crew1','Small crew',1,{suffix:'people',min:1})}${field('time.crew2','Large crew',10,{suffix:'people',min:1})}</div><div class="statline"><span>Total worker-hours</span><strong>${fmt(c.workerHours,2)}</strong></div>${[1,2].map((n)=>{const crew=num(state,`time.crew${n}`,n===1?1:10),days=safeDiv(safeDiv(c.workerHours,crew),num(state,'time.hoursDay',8));return `<div class="statline"><span>${crew} ${crew===1?'laborer':'laborers'}</span><strong>${fmt(days,2)} working days · ${fmt(safeDiv(days,num(state,'time.daysWeek',5)),2)} weeks</strong></div>`;}).join('')}<p class="small-note">Crew size is assumed to scale linearly; real schedules also depend on cure times, equipment, weather, and site access.</p></section>${details('how-material','How we calculate material costs',`<div class="reading"><h4>Worked example · supplied mulch defaults</h4><ol><li>Normalize: $3.67 ÷ 2 cu. ft. ≈ $1.84/cu. ft.</li><li>Average: ($1.84 + $1.79 + $1.84) ÷ 3 ≈ $1.82/cu. ft.</li><li>Convert: one cubic foot at 4 in. depth covers 3 sq. ft. Divide the full-precision average by 3: $0.607777…/sq. ft., displayed as $0.61.</li></ol><p>Fabric is already priced by area: ($0.16 + $0.10 + $0.15) ÷ 3 = $0.136666…/sq. ft. The model retains full precision. The lower listed figure is used when a source gives a price range.</p></div>`)}${details('how-labor','How we source labor',laborExplainer())}`;}
function originalScenarioControls(c){return `<section class="panel"><h3>Two alternatives for the same trail</h3><div class="controls-grid">${field(`${c.id}.cycle`,'Replacement cycle',c.surface.cycle,{suffix:'years',min:.000001})}${field('scenario.0.maintained','Scenario 1 · maintained',100,{suffix:'%',max:100})}${field('scenario.1.maintained','Scenario 2 · maintained',40,{suffix:'%',max:100})}${field('scenario.1.rebuilt','Scenario 2 · rebuilt at cycle end',100,{suffix:'%',max:100})}${field('condition','Condition-triggered annual allowance',5,{suffix:'%',max:100})}</div><p class="small-note">${e(c.surface.cycleSource)}. Scenario 1 rebuilt fraction = 100% − its maintained fraction.</p><p class="note">${fmt(c.scenarios[1].fraction*100,0)}% + ${fmt(c.scenarios[1].replaced*100,0)}% ≠ ${fmt((c.scenarios[1].fraction+c.scenarios[1].replaced)*100,0)}% of a single treatment. They happen at different stages: maintenance during the cycle, then reconstruction at the end.</p></section>`;}
function maintenanceReference(a){if(!a.reference)return '';const references=Array.isArray(a.reference)?a.reference:[a.reference];return `<section class="maintenance-reference" aria-label="Reference calculation for ${e(a.name)}"><div class="maintenance-reference-head"><div><p class="sectionlabel">Reference calculation</p><h4>How the supplied maintenance rates are calculated</h4></div><span class="reference-status">Planning benchmark</span></div>${references.map(r=>{const ih=r.hourly.map(x=>x/r.productivity),outCost=r.out.map(x=>x*r.quantity);return `<div class="maintenance-reference-method">${r.method?`<h5>${e(r.method)}</h5>`:''}<div class="maintenance-reference-grid"><div><span>Texas in-house role</span><strong>${e(r.role)}</strong><small>Salary Group ${e(r.group)} · ${money(r.hourly[0],2)}–${money(r.hourly[1],2)}/worker-hour</small></div><div><span>Reference productivity</span><strong>${fmt(r.productivity,2)} ${e(r.unit)}/hr</strong><small>${fmt(r.quantity,0)} ${e(r.unit)} ÷ ${fmt(r.hours,1)} worker-hours</small></div><div><span>In-house rate used</span><strong>${range(ih,4)}</strong><small>per ${e(r.unit)}</small></div><div><span>${e(r.sourceLabel||'Homewyse labor benchmark')}</span><strong>${range(outCost,2)}</strong><small>${fmt(r.quantity,0)} ${e(r.unit)} · ${e(r.location||'College Station, TX 77840')}</small></div><div><span>Outsourced rate used</span><strong>${range(r.out,4)}</strong><small>per ${e(r.unit)}</small></div></div><div class="reference-formulas"><div><b>In-house</b><span>${money(r.hourly[0],2)}–${money(r.hourly[1],2)} per hour ÷ ${fmt(r.productivity,2)} ${e(r.unit)} per hour = ${range(ih,4)} per ${e(r.unit)}</span></div><div><b>Outsourced</b><span>${range(outCost,2)} labor benchmark ÷ ${fmt(r.quantity,0)} ${e(r.unit)} = ${range(r.out,4)} per ${e(r.unit)}</span></div></div>${r.productivityNote?`<p class="maintenance-reference-scope"><strong>Productivity assumption:</strong> ${e(r.productivityNote)}</p>`:''}${r.scopeNote?`<p class="maintenance-reference-scope"><strong>Source fit:</strong> ${e(r.scopeNote)}</p>`:''}</div>`;}).join('')}<p class="maintenance-reference-note">These are planning benchmarks, not project bids. Confirm crew composition, scope, site conditions, equipment, materials, and local contractor quotes before budgeting.</p><div class="reference-resources"><h5>Resources</h5><ul><li><a href="${e(references[0].salaryUrl)}" target="_blank" rel="noopener noreferrer">Texas State Auditor · Salary Schedule A</a></li><li><a href="${e(references[0].roleUrl)}" target="_blank" rel="noopener noreferrer">Texas State Auditor · ${e(references[0].role)} job description</a></li><li><a href="${e(references[0].jobUrl)}" target="_blank" rel="noopener noreferrer">Texas State Auditor · Job description index</a></li>${references.map(r=>`<li><a href="${e(r.homewyseUrl)}" target="_blank" rel="noopener noreferrer">Homewyse · ${e(r.method||a.name)} benchmark</a></li>`).join('')}</ul></div></section>`;}
function maintenanceLaborForm(c,a){const mixed=['crack','joint'].includes(a.basis),linear=a.basis==='edge',service=a.serviceBased,label=service?'Services one worker completes in one hour *':linear?'Length one worker completes in one hour *':mixed?'Work completed by one worker in one hour *':'Area one worker completes in one hour *',suffix=service?'services/worker-hour':linear?'lin. ft./worker-hour':mixed?'work units/worker-hour':'sq. ft./worker-hour';return `<div class="customer-labor-tools maintenance-labor-tools"><h4>Add your maintenance labor rate</h4><p>Add a local crew or contractor estimate for ${e(a.name)}. The new option is selected automatically for its labor type.</p>${details('add-maintenance-labor-'+c.id+'-'+a.id,'+ Add maintenance labor option',`<form data-add-maintenance-labor="${c.id}" data-activity="${a.id}"><p class="small-note">Enter what one worker can complete in one hour. The calculator converts the hourly Low–High range into the activity rate used in annual and full-cycle maintenance totals.</p><div class="controls-grid"><label>Labor option *<select name="mode" required><option value="ih">In-house</option><option value="out">Outsourced</option></select></label><label>Crew or contractor name *<input name="name" required maxlength="200" placeholder="e.g., Parks maintenance crew"></label><label>Added by (your name) *<input name="contributor" required maxlength="120" placeholder="Enter your name"></label><label>Hourly labor rate · Low *<span class="form-input-with-suffix"><input name="lowHourly" type="number" min="0.000001" step="any" required placeholder="Low estimate"><span>$/worker-hour</span></span></label><label>Hourly labor rate · High *<span class="form-input-with-suffix"><input name="highHourly" type="number" min="0.000001" step="any" required placeholder="High estimate"><span>$/worker-hour</span></span></label><label>${label}<span class="form-input-with-suffix"><input name="productivity" type="number" min="0.000001" step="any" required placeholder="e.g., ${service?'0.5':'1,000'}"><span>${suffix}</span></span></label></div>${mixed?'<p class="small-note">Use sq. ft./worker-hour for an in-house area-based rate. Use lin. ft./worker-hour for an outsourced crack or joint rate.</p>':''}<div class="labor-formula"><span>Hourly labor rate</span><b>÷</b><span>Work completed per worker-hour</span><b>=</b><span>Maintenance labor rate</span></div><p class="product-form-error" role="alert"></p><button type="submit" class="primary">Add and use maintenance rate</button></form>`)}</div>`;}
function maintenanceLaborRows(c,a,mode){const selected=state.maintenanceLaborSelections?.[c.id]?.[a.id]?.[mode]??'default',custom=customMaintenanceLaborOptions(state,c.id,a.id,mode),base=a[mode],pre=a.prefix+'.'+mode,missing=!base&&!has(state,pre+'.low')&&!has(state,pre+'.high'),reference=[num(state,pre+'.low',base?.[0]??0),num(state,pre+'.high',base?.[1]??0)],unit=a.serviceBased?'service':a.basis==='edge'||mode==='out'&&['crack','joint'].includes(a.basis)?'lin. ft.':'sq. ft.',visitSuffix=a.visitBased&&!a.serviceBased?' per visit':'';return `<tr class="${selected==='default'?'labor-selected':''}"><td><label class="labor-choice"><input type="radio" name="maintenance-labor-${c.id}-${a.id}-${mode}" data-maintenance-labor-select="${c.id}" data-activity="${a.id}" data-mode="${mode}" data-index="default" ${selected==='default'?'checked':''}><span><strong>${modeName(mode)}</strong><small>Supplied reference</small></span></label></td><td>${field(pre+'.low','Low rate',base?.[0]??null,{placeholder:'n/a'})}</td><td>${field(pre+'.high','High rate',base?.[1]??null,{placeholder:'n/a'})}</td><td class="numeric">${missing?'n/a — no published rate':range(reference,4)}<small class="calculation-note">$/${unit}${visitSuffix}</small></td><td></td></tr>${custom.map((x,i)=>{const rates=[safeDiv(x.lowHourly,x.productivity),safeDiv(x.highHourly,x.productivity)],active=selected===i;return `<tr class="${active?'labor-selected':''}"><td><label class="labor-choice"><input type="radio" name="maintenance-labor-${c.id}-${a.id}-${mode}" data-maintenance-labor-select="${c.id}" data-activity="${a.id}" data-mode="${mode}" data-index="${i}" ${active?'checked':''}><span><strong>${e(x.name)}</strong><small>${mode==='ih'?'In-house':'Outsourced'} · Added by ${e(x.contributor)}</small></span></label></td><td><strong>${money(rates[0],4)}</strong><small class="calculation-note">${money(x.lowHourly,2)}/hr ÷ ${fmt(x.productivity,2)} ${unit}/worker-hour</small></td><td><strong>${money(rates[1],4)}</strong><small class="calculation-note">${money(x.highHourly,2)}/hr ÷ ${fmt(x.productivity,2)} ${unit}/worker-hour</small></td><td class="numeric">${range(rates,4)}<small class="calculation-note">$/${unit}${visitSuffix}</small></td><td><button type="button" class="delete-product small" data-delete-maintenance-labor="${c.id}" data-activity="${a.id}" data-mode="${mode}" data-index="${i}" aria-label="Delete ${e(x.name)}">Delete</button></td></tr>`;}).join('')}`;}
function maintenanceLaborEditor(c,a){return `${maintenanceReference(a)}${maintenanceLaborForm(c,a)}<p class="small-note"><strong>Choose one option for each labor type.</strong> The selected rate is used for this activity in both maintenance scenarios.</p><div class="table-scroll"><table class="labor-options-table"><thead><tr><th>Use this labor option</th><th>Low rate</th><th>High rate</th><th class="numeric">Calculated rate · Low–High</th><th>Action</th></tr></thead><tbody>${maintenanceLaborRows(c,a,'ih')}${maintenanceLaborRows(c,a,'out')}</tbody></table></div>`;}
function maintenanceInputs(c){return details('maintenance-inputs','Show detail · maintenance rates, frequencies & quantities',`${field('condition','Condition-triggered annual allowance',5,{suffix:'%',max:100})}<p class="small-note">Used only for activities scheduled by condition rather than a fixed interval.</p>${(c.id==='asphalt'||c.id==='concrete')?`<div class="controls-grid">${c.id==='asphalt'?field(`${c.id}.crack`,'Crack length (optional)',null,{suffix:'lin. ft.'}):field(`${c.id}.joint`,'Joint length (optional)',null,{suffix:'lin. ft.'})}${c.id==='concrete'?c.scenarios.map((sc,n)=>field(`${c.id}.remesh.${n}`,`Remesh area · Scenario ${n+1}`,sc.MA,{suffix:'sq. ft.'})).join(''):''}</div><p class="small-note">Blank crack or joint lengths contribute zero material and linear-foot contractor costs. In-house labor for these activities still follows the maintained trail area.</p>`:''}${c.scenarios[0].activities.map(a=>details(`activity-${a.id}`,e(a.name),`<p class="small-note">${a.serviceBased?'Labor only · one service treats up to 100 weeds':a.visitBased?'Labor only · full maintained area per visit':e(a.tier)+' · '+e(a.unit)}</p><div class="controls-grid">${a.visitBased?field(`${a.prefix}.visits`,'Visits per year',a.visits):a.interval!==null?field(`${a.prefix}.interval`,'Maintenance interval',c.surface.activities.find(x=>x.id===a.id).interval,{suffix:'years',min:.000001}):'<p class="small-note">Uses the editable condition-triggered allowance above.</p>'}${a.serviceBased?field(`${a.prefix}.services`,'Services per visit',a.services??1,{suffix:'services',min:.000001}):''}${a.category?field(`${a.prefix}.materialCost`,'Material cost per unit',category(state,a.category).cost,{suffix:'$/'+a.unit}):''}${!a.visitBased?c.scenarios.map((sc,n)=>field(`${a.prefix}.basis.${n}`,`Material basis · S${n+1}`,sc.activities.find(x=>x.id===a.id).autoBasis,{suffix:a.unit})).join(''):''}</div>${maintenanceLaborEditor(c,a)}${a.id==='weed'?'<p class="small-note">Default schedule: 12 visits per year × 1 service per visit. Adjust both inputs to reflect the number of weeds and the local growing season.</p>':''}${a.category?details(`act-products-${a.id}`,'Show source products',productEditor(a.category)):''}`)).join('')}`);}
function maintenanceTables(c,sc,n){return details(`maintenance-tables-${n}`,`Show detail · Scenario ${n+1} material, labor & schedule`,`<h4>Maintenance materials</h4><div class="table-scroll"><table><thead><tr><th>Activity</th><th>Annual share</th><th>Basis quantity</th><th>Annual quantity</th><th class="numeric">Annual material · Low – High</th><th class="numeric">Full-cycle material · Low – High</th></tr></thead><tbody>${sc.activities.filter(a=>!a.visitBased).map(a=>`<tr><td>${e(a.name)}</td><td>${fmt(a.share*100,2)}%${a.share===0?'<div class="small-note">Superseded by replacement</div>':''}</td><td>${fmt(a.basis,2)} ${a.unit}</td><td>${fmt(a.quantity,2)} ${a.unit}</td><td class="numeric">${range([a.annual.material,a.annual.material])}</td><td class="numeric">${range([a.full.material,a.full.material])}</td></tr>`).join('')}<tr class="total-row"><td colspan="4">Material subtotal</td><td class="numeric">${range([sc.annual.material,sc.annual.material])}</td><td class="numeric">${range([sc.full.material,sc.full.material])}</td></tr></tbody></table></div><h4>Maintenance labor</h4><div class="table-scroll"><table><thead><tr><th>Activity</th><th>Labor</th><th>Annual labor quantity</th><th class="numeric">Annual labor · Low – High</th><th class="numeric">Full-cycle labor · Low – High</th></tr></thead><tbody>${sc.activities.map(a=>modes().map(m=>`<tr><td>${e(a.name)}</td><td>${modeName(m)}</td><td>${fmt(m==='ih'?a.ihQuantity:a.outQuantity,2)} ${a.visitBased?'sq. ft.-visits':a.basis==='edge'?'lin. ft.':m==='out'?a.unit:'sq. ft.'}</td><td class="numeric">${m==='out'&&a.missing?'n/a — no published rate':range(a.annual.labor[m])}</td><td class="numeric">${m==='out'&&a.missing?'n/a — no published rate':range(a.full.labor[m])}</td></tr>`).join('')).join('')}${modes().map(m=>`<tr class="subtotal"><td colspan="3">${modeName(m)} · labor subtotal</td><td class="numeric">${range(sc.annual.labor[m])}</td><td class="numeric">${range(sc.full.labor[m])}</td></tr>`).join('')}</tbody></table></div><h4>Activity schedule over ${c.C} years</h4><p class="small-note">Cost per occurrence = full-cycle cost ÷ times performed. Condition-triggered work represents one annual allowance, not a forecast of individual failures.</p><div class="table-scroll"><table><thead><tr><th>Activity</th><th>Interval / years</th><th>Times over cycle</th><th class="numeric">Materials / occurrence</th>${modes().map(m=>`<th class="numeric">${modeName(m)} labor / occurrence</th><th class="numeric">${modeName(m)} total / occurrence</th>`).join('')}</tr></thead><tbody>${sc.activities.map(a=>`<tr><td>${e(a.name)}</td><td>${a.interval===null?'Condition-triggered':fmt(a.interval,3)}</td><td>${fmt(a.times,2)}</td><td class="numeric">${range([safeDiv(a.full.material,a.times),safeDiv(a.full.material,a.times)])}</td>${modes().map(m=>`<td class="numeric">${m==='out'&&a.missing?'n/a — no published rate':range(a.full.labor[m].map(x=>safeDiv(x,a.times)))}</td><td class="numeric">${range(a.full[m].map(x=>safeDiv(x,a.times)))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);}
function originalMaintenance(c){return `${heading('Step 02 · Maintenance & Operations','What will it take to keep it usable?','Compare continuous maintenance with reduced upkeep followed by a scheduled rebuild.')}<div class="formula">Task cost per unit × frequency per year = annual maintenance cost</div>${scenarioControls(c)}<div class="two-col">${c.scenarios.map((sc,n)=>`<section class="panel scenario-card ${n===1?'scenario-two':''}"><div class="scenario-title"><span class="scenario-index">S${n+1}</span><h3>${n===0?'Maintain-and-Extend':'Reduced Maintenance +<br>Scheduled Reconstruction'}</h3></div><p>${n===0?'Keep up with maintenance so the trail does not need to be rebuilt at the end of the cycle.':'Maintain part of the trail during the cycle, then rebuild the specified share at the end.'}</p><div class="statline"><span>Maintained area</span><strong>${fmt(sc.MA,0)} sq. ft. · ${fmt(sc.fraction*100,0)}%</strong></div><div class="statline"><span>Rebuilt at cycle end</span><strong>${fmt(sc.replaced*100,0)}%</strong></div><div class="timeline"><span>Year 0<br>Start</span><span>Years 1–${c.C}<br>Maintain</span><span>Year ${c.C}<br>${sc.replaced>0?`${fmt(sc.replaced*100,0)}% rebuild`:'Continue use'}</span></div><h4>Maintenance per year</h4>${resultCards(sc.annual,'Annual maintenance')}<h4>Maintenance over ${c.C} years</h4>${resultCards(sc.full,'Full-cycle maintenance')}</section>`).join('')}</div><section class="panel"><h3>Share of trail addressed</h3><p class="small-note">Maintenance and rebuilding occur at different stages; the bars are not added.</p><div class="bars">${c.scenarios.map((sc,n)=>[['Maintained',sc.fraction],['Rebuilt',sc.replaced]].map(([t,v])=>`<div class="bar-row"><span>S${n+1} · ${t}</span><div class="bar-track"><div class="bar ${t==='Rebuilt'?'gold':''}" style="width:${Math.max(0,Math.min(100,v*100))}%"></div></div><strong>${fmt(v*100,0)}%</strong></div>`).join('')).join('')}</div></section>${maintenanceInputs(c)}${c.scenarios.map((sc,n)=>maintenanceTables(c,sc,n)).join('')}${adjustments()}<p class="small-note">Missing published contractor rates contribute zero until you enter a local rate.</p>`;}
function replacement(c){return `<section class="panel" id="replacement-costs"><h3>Replacement & removal budget</h3><p class="small-note">A full rebuild of the supplied construction layers. Scenario fractions are applied in the lifecycle totals below.</p><div class="table-scroll"><table><thead><tr><th>Replacement layer</th><th>Quantity</th><th class="numeric">Unit price</th><th class="numeric">Material cost · Low – High</th></tr></thead><tbody>${c.layers.map(l=>`<tr><td>${e(l.name)}</td><td>${field(`${c.id}.replacement.${l.key}`,'Replacement quantity',l.quantity,{suffix:l.unit})}</td><td class="numeric">${money(l.cost,4)}</td><td class="numeric">${range([l.replacementTotal,l.replacementTotal])}</td></tr>`).join('')}<tr class="subtotal"><td colspan="3">Replacement material subtotal</td><td class="numeric">${range([c.replacement.material,c.replacement.material])}</td></tr>${modes().map(m=>`<tr><td colspan="3">Replacement labor · ${modeName(m)} (construction rate × area)</td><td class="numeric">${range(c.replacement.labor[m])}</td></tr>`).join('')}</tbody></table></div><div class="controls-grid">${field(`${c.id}.demo.low`,'Removal & haul-away · low',c.surface.demo[0],{suffix:'$/sq. ft.'})}${field(`${c.id}.demo.high`,'Removal & haul-away · high',c.surface.demo[1],{suffix:'$/sq. ft.'})}</div><div class="statline"><span>Reconstruction: demolition, removal & haul-away</span><strong>${range(c.demo)}</strong></div><div style="margin-top:18px">${resultCards(c.replacement,'Full replacement + removal')}</div></section>`;}
function ownershipTable(c){const rows=[['Construction material',null,sc=>[c.construction.material,c.construction.material]],['Construction labor · in-house','ih',sc=>c.construction.labor.ih],['Construction labor · outsourced','out',sc=>c.construction.labor.out],['Maintenance material · full cycle',null,sc=>[sc.full.material,sc.full.material]],['Maintenance labor · in-house','ih',sc=>sc.full.labor.ih],['Maintenance labor · outsourced','out',sc=>sc.full.labor.out],['Reconstruction × rebuilt fraction',null,sc=>c.demo.map(x=>x*sc.replaced)],['Replacement material × rebuilt fraction',null,sc=>[c.replacement.material*sc.replaced,c.replacement.material*sc.replaced]],['Replacement labor · in-house × rebuilt fraction','ih',sc=>c.replacement.labor.ih.map(x=>x*sc.replaced)],['Replacement labor · outsourced × rebuilt fraction','out',sc=>c.replacement.labor.out.map(x=>x*sc.replaced)]];return `<div class="table-scroll"><table><thead><tr><th>Cost component</th><th class="numeric">S1 Low</th><th class="numeric">S1 High</th><th class="numeric">S2 Low</th><th class="numeric">S2 High</th></tr></thead><tbody>${rows.filter(x=>!x[1]||modes().includes(x[1])).map(([label,m,fn])=>`<tr><td>${label}</td>${c.scenarios.flatMap(sc=>fn(sc)).map(x=>`<td class="numeric">${money(x)}</td>`).join('')}</tr>`).join('')}${modes().map(m=>`<tr class="total-row"><td>Total · ${modeName(m)}</td>${c.scenarios.flatMap(sc=>sc.total[m]).map(x=>`<td class="numeric">${money(x)}</td>`).join('')}</tr><tr class="subtotal"><td>Adjusted total · ${modeName(m)}</td>${c.scenarios.flatMap(sc=>adjusted(state,sc.total[m])).map(x=>`<td class="numeric">${money(x)}</td>`).join('')}</tr><tr><td>Average annual ownership · ${modeName(m)}</td>${c.scenarios.flatMap(sc=>sc.perYear[m]).map(x=>`<td class="numeric">${money(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="small-note">Each total uses one labor mode. In-house and contractor labor rows are alternatives, as are Scenarios 1 and 2.</p>`;}
function compareAll(){const all=comparison(state),metric=val(state,'compare.metric','perYear'),sn=Number(val(state,'compare.scenario',state.summaryScenario));const max=Math.max(1,...all.flatMap(c=>modes().map(m=>metric==='construction'?c.construction[m][1]:c.scenarios[sn][metric][m][1])));const labels={perYear:'Average annual ownership',total:'Full-cycle lifecycle cost',annual:'Annual maintenance',construction:'Construction cost'};return `<section class="panel" id="compare-surfaces"><div class="panel-head"><div><h3>Compare all five surfaces</h3><p class="small-note">Same trail area: ${fmt(area(state),0)} sq. ft. · individual surface assumptions retained</p></div></div><div class="controls-grid no-print"><div><label for="compare-metric">Cost measure</label><select id="compare-metric"><option value="perYear" ${metric==='perYear'?'selected':''}>Average annual ownership</option><option value="total" ${metric==='total'?'selected':''}>Full-cycle lifecycle cost</option><option value="annual" ${metric==='annual'?'selected':''}>Annual maintenance</option><option value="construction" ${metric==='construction'?'selected':''}>Construction cost</option></select></div><div><label for="compare-scenario">Maintenance scenario</label><select id="compare-scenario"><option value="0" ${sn===0?'selected':''}>Scenario 1 · Maintain-and-Extend</option><option value="1" ${sn===1?'selected':''}>Scenario 2 · Reduced Maintenance + Rebuild</option></select></div></div><h4>${labels[metric]} · Scenario ${sn+1}</h4><p class="small-note">Solid segments mark Low–High ranges; lighter bars show the distance from zero. All figures are unadjusted.</p><div class="comparison-chart" role="img" aria-label="${labels[metric]} range comparison; exact values in the table below">${all.map(c=>`<div class="chart-group"><h4>${e(c.surface.name)} <span class="small-note">· ${c.C} years</span></h4>${modes().map(m=>{const r=metric==='construction'?c.construction[m]:c.scenarios[sn][metric][m];return `<div class="comparison-line"><span class="line-label">${m==='ih'?'In-house':'Outsourced'}</span><div class="range-chart ${m==='out'?'gold':''}"><span class="track" style="width:${Math.max(0,r[1]/max*100)}%"></span><span class="range-segment" style="left:${Math.max(0,r[0]/max*100)}%;width:${Math.max(.2,(r[1]-r[0])/max*100)}%"></span></div><span class="line-value">${range(r,0)}</span></div>`;}).join('')}</div>`).join('')}</div><div class="table-scroll"><table><thead><tr><th>Surface / cycle</th><th>Labor</th><th class="numeric">Construction</th><th class="numeric">Maintenance / year</th><th class="numeric">Full lifecycle</th><th class="numeric">Ownership / year</th></tr></thead><tbody>${all.map(c=>modes().map(m=>`<tr><td>${e(c.surface.name)}<div class="small-note">${c.C} years</div></td><td>${m==='ih'?'In-house':'Outsourced'}</td><td class="numeric">${range(c.construction[m])}</td><td class="numeric">${range(c.scenarios[sn].annual[m])}</td><td class="numeric">${range(c.scenarios[sn].total[m])}</td><td class="numeric">${range(c.scenarios[sn].perYear[m])}</td></tr>`).join('')).join('')}</tbody></table></div><p class="comparison-warning">Cycles differ (${all.map(c=>c.C).join(', ')} years). Average annual ownership = full-cycle total ÷ cycle years; it is a simple undiscounted average. Missing published contractor maintenance rates count as zero and can understate those comparisons.</p></section>`;}
function staffing(c){return details('staffing','Show staffing detail · in-house FTE & peak-year needs',`<p class="small-note">One FTE-year is the work of one full-time position for a year. It measures work volume, not crew size. Construction and replacement are one-time effort; maintenance is annual.</p><div class="controls-grid">${field('fte.nominal','Nominal hours / FTE-year',2080,{min:.000001})}${field('fte.realistic','Productive field hours / FTE-year',1800,{min:.000001})}${field(`${c.id}.hourly`,'Implied in-house hourly rate',c.hourlyDefault,{suffix:'$/hr',min:.000001})}${field(`${c.id}.demoProductivity`,'Demolition productivity (optional)',null,{suffix:'sq. ft./hr',min:.000001})}</div><div class="statline"><span>Construction worker-hours</span><strong>${fmt(c.workerHours,2)}</strong></div><div class="statline"><span>Construction FTE-year · nominal / realistic</span><strong>${fmt(c.constructionFte,3)} / ${fmt(c.constructionReal,3)}</strong></div><div class="statline"><span>Construction person-months · nominal</span><strong>${fmt(c.constructionFte*12,2)}</strong></div><div class="table-scroll"><table><thead><tr><th>Effort</th><th class="numeric">Scenario 1 nominal</th><th class="numeric">Scenario 1 realistic</th><th class="numeric">Scenario 2 nominal</th><th class="numeric">Scenario 2 realistic</th></tr></thead><tbody>${[['Annual maintenance FTE','annualNom','annualReal'],['Replacement-year FTE','replacementNom','replacementReal'],['Peak-year total FTE','peakNom','peakReal']].map(([label,a,b])=>`<tr><td>${label}</td>${c.scenarios.flatMap(sc=>[sc.fte[a],sc.fte[b]]).map(x=>`<td class="numeric">${fmt(x,3)}</td>`).join('')}</tr>`).join('')}<tr><td>Annual maintenance person-months</td>${c.scenarios.flatMap(sc=>[sc.fte.annualNom*12,sc.fte.annualReal*12]).map(x=>`<td class="numeric">${fmt(x,2)}</td>`).join('')}</tr></tbody></table></div>${c.scenarios.map((sc,n)=>sc.fte.peakNom>1||sc.fte.peakReal>1?`<p class="note">Scenario ${n+1}: Work exceeds one full-time position in that year — plan a temporary hire or contract in advance.</p>`:'').join('')}${details('fte-productivities','Edit maintenance productivity by activity',`<div class="table-scroll"><table><thead><tr><th>Activity</th><th>Productivity · sq. ft./worker-hour</th><th class="numeric">S1 annual worker-hours</th><th class="numeric">S2 annual worker-hours</th></tr></thead><tbody>${c.scenarios[0].activities.map((a,i)=>`<tr><td>${e(a.name)}</td><td>${field(`${a.prefix}.productivity`,'Maintenance productivity',a.productivityDefault,{min:.000001})}</td><td class="numeric">${fmt(a.hours,2)}</td><td class="numeric">${fmt(c.scenarios[1].activities[i].hours,2)}</td></tr>`).join('')}</tbody></table></div>`)}<p class="small-note">Default maintenance productivity = implied hourly rate ÷ the activity’s in-house low rate. Demolition is excluded unless you enter a productivity. Contractor crews consume no agency FTE. The implied hourly rate may exclude fringe benefits, noted in the source model as typically 30–35% of base for Texas local government.</p>`);}
function originalLifecycle(c){return `${heading('Step 03 · Replacement & Lifecycle','What will it cost to own?','Bring construction, maintenance, and end-of-cycle work into one comparison.')} ${scenarioControls(c)}${replacement(c)}<section class="panel"><h3>Full-cycle cost of ownership · ${c.C} years</h3><div class="two-col">${c.scenarios.map((sc,n)=>`<div><h4>Scenario ${n+1} · ${n===0?'Maintain-and-Extend':'Reduced Maintenance + Rebuild'}</h4>${resultCards(sc.total,'Full-cycle ownership')}<div style="margin-top:14px">${modes().map(m=>`<div class="statline"><span>${m==='ih'?'In-house':'Outsourced'} / year</span><strong>${range(sc.perYear[m])}</strong></div>`).join('')}</div></div>`).join('')}</div>${details('ownership-components','Show detail · every lifecycle cost component',ownershipTable(c))}</section>${compareAll()}${staffing(c)}${adjustments()}<p class="lede">Each lens uses one table. Together they answer a single question: is this project feasible to build and to own?</p>`;}
function methods(){return `${heading('Methods & Sources','Understand the estimate.','All defaults come from the supplied July 2026 reference tables. Edit any price or assumption in the calculator.')}<section class="panel reading"><h3>Pricing and conversions</h3><p>Retail prices retained verbatim from the reference tables (Home Depot / Lowe’s listings and industry budget ranges), July 2026. Standard thicknesses are planning defaults — confirm against project drawings before ordering.</p><p>Cost per estimating unit = cost per purchase unit ÷ coverage per purchase unit. Category averages are unweighted arithmetic means of converted product prices. Calculations keep full precision; display values are rounded.</p><p>Hot-mix asphalt is averaged separately from repair-only patch products. Crushed-rock base is separate from gravel grids. Steel remesh, linear-foot rebar, and expansion joints are separate categories.</p><p class="note">The concrete slab average combines bagged mixes and ready-mix references. Bagged concrete runs about 2.4 times ready-mix in the supplied list. Confirm the intended procurement route before using the average as a project quote.</p></section><section class="panel"><h3>Conversion standards & source links</h3><div class="table-scroll"><table><thead><tr><th>Material / activity</th><th>Standard and conversion</th><th>Source supplied with the toolkit</th></tr></thead><tbody>${sourceRows.map(([a,b,c,url])=>`<tr><td>${e(a)}</td><td>${e(b)}</td><td>${url?`<a href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(c)}</a>`:e(c)}</td></tr>`).join('')}</tbody></table></div></section>${details('methods-labor','Labor sourcing',laborExplainer()+laborLibrary())}<section class="panel reading" id="maintenance-rules"><h3>Maintenance model rules</h3><ul class="methods-list"><li>Maintained area = trail area × the scenario’s maintained fraction.</li><li>Interval-based material activities use an annual share of 1 ÷ replacement cycle. If the maintenance interval is at least the replacement cycle, the annual share is zero under the supplied superseded-by-replacement rule. This rule is applied to both scenarios as specified.</li><li>Condition-triggered work uses a 5% annual allowance by default. Routine inspection uses the maintained area per visit. Weed control uses service units, with one service representing treatment of up to 100 weeds.</li><li>Crack and joint material quantities use the entered linear feet. Contractor linear-foot labor uses that same annual length. In-house labor uses the annual share of maintained area.</li><li>Edge-repair material and labor use the project’s entered edge length.</li><li>Annual material and labor costs × cycle years give full-cycle maintenance. Unknown contractor rates show “n/a — no published rate” and contribute zero until replaced with a local rate.</li><li>Activity counts: interval-based = max(1, floor(cycle ÷ interval)); visit-based = floor(cycle × visits/year); condition-triggered = cycle years. With zero visits, costs and cost per occurrence are zero.</li><li>Scenario 1 replaced fraction = 1 − its maintained fraction. Scenario 2 uses its separate rebuilt fraction. These are modeling assumptions, not evidence that maintenance guarantees indefinite service life.</li><li>Full ownership = construction + full-cycle maintenance + (replacement + removal) × rebuilt fraction. The scenarios are alternatives; never add them together.</li><li>Average annual ownership is full-cycle ownership divided by cycle years. No discounting, escalation, or inflation is applied.</li></ul></section><section class="panel reading"><h3>Staffing and construction time</h3><p>Worker-hours = area ÷ productivity. Elapsed hours = worker-hours ÷ crew size. Divide by working hours per day and working days per week to get days and weeks.</p><p>Nominal FTE uses 2,080 hours per year. The realistic field-hours denominator is 1,800. Both can be changed. Maintenance productivity is derived from implied hourly wage ÷ the activity’s in-house low unit labor rate. A higher wage estimate does not imply more hours of work.</p><p>Peak-year effort combines that year’s maintenance with replacement effort. Demolition effort is included only when an in-house demolition productivity is entered.</p></section><h3>Full product lists & editable defaults</h3><p class="small-note">Editing these defaults updates every relevant estimate on the site. Source descriptions retain the original reference wording.</p>${Object.keys(categories).map(key=>details(`source-${key}`,e(categories[key].name),productEditor(key))).join('')}${details('reference-only','Reference-only products · excluded from totals',`<p class="small-note">These products are retained for reference and are not included in category averages or costs.</p><div class="controls-grid">${field('reference.rebar1','3/8 in. × 10 ft. #3 steel rebar',.50,{suffix:'$/lin. ft.'})}${field('reference.rebar2','Typical steel rebar category',.50,{suffix:'$/lin. ft.'})}${field('reference.weed','Roundup Weed and Grass Killer 4, 1 gal',.06,{suffix:'$/sq. ft.'})}</div><p class="small-note">Rebar needs a spacing assumption to convert to area pricing. Weed control is labor-only in this model. Typical steel rebar reference range: $0.50–$1.00 per linear foot.</p>`)}`;}
function summaryText(){const c=calculate(state),lines=['Feasibility Toolbox — Rural Park & Trail Planning Toolkit',`${c.surface.name} | ${fmt(c.A,0)} sq. ft. | ${c.C}-year cycle`,'Texas reference pricing: July 2026',''];for(const m of modes()){lines.push(`${modeName(m)} construction: ${range(c.construction[m])}`);c.scenarios.forEach((sc,i)=>lines.push(`Scenario ${i+1}: ${(sc.fraction*100).toFixed(1)}% maintained, ${(sc.replaced*100).toFixed(1)}% rebuilt; annual maintenance ${range(sc.annual[m])}; lifecycle ${range(sc.total[m])}; average annual ownership ${range(sc.perYear[m])}; adjusted lifecycle ${range(adjusted(state,sc.total[m]))}.`));}lines.push('',`Estimate adjustment: ${num(state,'adj.low',-15)}% / ${num(state,'adj.high',15)}%.`,`${Object.keys(state.overrides).filter(k=>!k.startsWith('compare.')).length} edited inputs. Unknown published rates contribute zero.`, 'Planning-level estimate; confirm quantities, thicknesses, and local quotes.');return lines.join('\n');}
function printReport(c){return `<div><p class="eyebrow">Toolbox 01 · Project Feasibility</p><h2>Rural Park & Trail Planning Toolkit</h2><p>Yang Song, Zipeng Guo · Texas pricing, July 2026</p><h3>${e(c.surface.name)} · ${fmt(c.A,0)} sq. ft. · ${c.C}-year cycle</h3><p class="small-note">${Object.keys(state.overrides).filter(k=>!k.startsWith('compare.')).length} edited inputs. Estimate adjustment ${num(state,'adj.low',-15)}% / ${num(state,'adj.high',15)}%.</p><h3>Construction</h3>${resultCards(c.construction,'Materials + labor')}<div class="table-scroll"><table><thead><tr><th>Layer</th><th>Quantity</th><th>Unit price</th><th>Cost</th></tr></thead><tbody>${c.layers.map(l=>`<tr><td>${e(l.name)}</td><td>${fmt(l.quantity,2)} ${l.unit}</td><td>${money(l.cost,4)}</td><td>${range([l.total,l.total])}</td></tr>`).join('')}</tbody></table></div><p>Worker-hours: ${fmt(c.workerHours,2)}. Nominal construction FTE-year: ${fmt(c.constructionFte,3)}.</p><div class="print-section"><h3>Maintenance</h3>${c.scenarios.map((sc,n)=>`<h4>Scenario ${n+1}: ${fmt(sc.fraction*100,0)}% maintained / ${fmt(sc.replaced*100,0)}% rebuilt</h4>${resultCards(sc.annual,'Annual maintenance')}${resultCards(sc.full,'Cycle-long maintenance')}${maintenanceTables(c,sc,n)}`).join('')}</div><div class="print-section"><h3>Lifecycle ownership · ${c.C} years</h3>${stageBreakdown(c)}${ownershipTable(c)}</div><div class="print-section">${compareAll()}</div>${Object.keys(state.overrides).length?`<div class="print-section"><h3>Edited assumptions</h3><table><tbody>${Object.entries(state.overrides).filter(([k])=>!k.startsWith('compare.')).map(([k,v])=>`<tr><td>${e(k)}</td><td>${e(v)}</td></tr>`).join('')}</tbody></table></div>`:''}</div>`;}
function render(){fieldCount=0;const open=new Set([...document.querySelectorAll('details[open]')].map(x=>x.dataset.panel));const c=calculate(state);const views={overview,construction,maintenance,lifecycle,methods};app.innerHTML=`${printing?'':header(c)}<div class="shell"><main id="main" class="view-${state.step}" tabindex="-1">${invalidKeys.size?'<div class="error-banner" role="alert">Check the highlighted fields. Required quantities and denominators must be positive, percentages must stay within their limits, and low rates cannot exceed high rates. Correct these values before using or exporting the estimate.</div>':''}${printing?printReport(c):views[state.step](c)}${printing?'':`<div class="bottom-nav"><button data-step="${({construction:'overview',maintenance:'construction',lifecycle:'maintenance',methods:'overview',overview:'overview'})[state.step]}" ${state.step==='overview'?'style="visibility:hidden"':''}>Back</button><span class="small-note">${state.step==='overview'?'Understanding Feasibility':state.step==='methods'?'Pricing & model documentation':`Step ${['construction','maintenance','lifecycle'].indexOf(state.step)+1} of 3`}</span><button class="primary" data-step="${({overview:'construction',construction:'maintenance',maintenance:'lifecycle',lifecycle:'methods',methods:'construction'})[state.step]}">${state.step==='lifecycle'?'Methods & sources':state.step==='methods'?'Back to calculator':state.step==='overview'?'Explore project costs':'Next'}</button></div>`}</main>${printing||state.step==='overview'||state.step==='methods'?'':`<section class="exports" aria-label="Export and reset"><div><div class="actions"><button data-action="csv" ${invalidKeys.size?'disabled':''}>Export results (CSV)</button><button data-action="print" ${invalidKeys.size?'disabled':''}>Print / Save as PDF</button><button data-action="copy" ${invalidKeys.size?'disabled':''}>Copy shareable summary</button></div><p class="caption">Your edits stay on this page. Export or copy your results before closing it.</p></div><button class="text" data-action="reset-all">↺ Reset all to defaults</button></section>`}</div><footer><div class="shell footer-row"><p>Toolbox 01 · Project Feasibility — Rural Park & Trail Planning Toolkit. Texas pricing, July 2026 (Home Depot, Lowe’s, agency and industry sources). Planning-level estimates only; confirm quantities and thicknesses against project drawings and local quotes.</p><p>Yang Song, Zipeng Guo</p></div></footer>`;document.querySelectorAll('details').forEach(d=>{if(open.has(d.dataset.panel)||printing)d.open=true;});}
function validate(){invalidKeys.clear();for(const [key,raw] of Object.entries(state.overrides)){const meta=registry.get(key);if(!meta||key.startsWith('compare.'))continue;if(meta.text){if(meta.required&&!String(raw).trim())invalidKeys.add(key);continue;}if(raw===''&&!meta.required)continue;const v=Number(raw);if(!Number.isFinite(v)||(meta.required&&raw==='')||v<(meta.min??0)||(meta.max!==undefined&&v>meta.max))invalidKeys.add(key);}for(const [key,meta] of registry){if(key.endsWith('.low')){const high=key.slice(0,-4)+'.high',hMeta=registry.get(high);if(hMeta&&Number(val(state,key,meta.def))>Number(val(state,high,hMeta.def))&&val(state,high,hMeta.def)!==null){invalidKeys.add(key);invalidKeys.add(high);}}}if(area(state)<=0)invalidKeys.add('area');}
function refreshKeepingFocus(input){const key=input.dataset.key;const peers=[...document.querySelectorAll('input[data-key]')].filter(x=>x.dataset.key===key),idx=peers.indexOf(input);const start=input.selectionStart,end=input.selectionEnd;const scroll=window.scrollY;render();const next=[...document.querySelectorAll('input[data-key]')].filter(x=>x.dataset.key===key)[idx];if(next){input.id=next.id;if(next.hasAttribute('aria-invalid'))input.setAttribute('aria-invalid','true');else input.removeAttribute('aria-invalid');next.replaceWith(input);input.focus({preventScroll:true});if(input.type==='text'&&start!==null)input.setSelectionRange(start,end);}window.scrollTo({top:scroll,behavior:'instant'});}
function navigate(step,target='',push=true){if(!['overview','construction','maintenance','lifecycle','methods'].includes(step))return;state.step=step;if(!['overview','methods'].includes(step))lastCalculatorStep=step;render();if(push&&typeof history!=='undefined')history.pushState(null,'','#'+step+(target?'/'+target:''));if(target&&revealTarget(target))return;if(step==='construction'&&revealTarget('project-editor'))return;document.querySelector('#main').scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('#main').focus({preventScroll:true});}
function notify(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('show'),4200);}
let lastCalculatorStep='construction';
const photoData={mulch:{slide:6,caption:'Mulch / wood chip trail',description:'A wood-chip walking surface over separation fabric.'},gravel:{slide:7,caption:'Gravel trail',description:'Pea gravel above a compacted crushed-rock base, with fabric and edging.'},dg:{slide:8,caption:'Decomposed granite trail',description:'A compacted granite surface with a stabilizer, separation fabric, and edging.'},asphalt:{slide:9,caption:'Asphalt trail',description:'A hot-mix asphalt surface with a protective treatment.'},concrete:{slide:10,caption:'Concrete trail',description:'A concrete slab with cure and seal treatment and embedded steel remesh.'}};
const go=(step,target,label,cls='context-link')=>`<a class="${cls}" href="#${step}${target?'/'+target:''}" data-go="${step}" data-target="${target}">${label}</a>`;
const readLink=(target)=>go('overview',target,'Read the explanation','read-link');
function photo(id,large=false){const p=photoData[id];return `<figure class="material-photo ${large?'large-photo':''}"><button class="photo-button" data-photo="${id}" aria-label="Enlarge reference photograph: ${e(p.caption)}"><img src="assets/${id}.png" alt="${e(p.caption)} reference photograph" loading="lazy" width="600" height="360"><span>Enlarge photo</span></button><figcaption>${e(p.caption)} · reference photograph</figcaption></figure>`;}
function stageLegend(){return `<div class="stage-legend"><span class="stage-construction">1 · Construction</span><span class="stage-maintenance">2 · Maintenance</span><span class="stage-replacement">3 · Replacement</span></div>`;}
function header(c){const calc=!['overview','methods'].includes(state.step),sc=c.scenarios[state.summaryScenario];return `<header class="masthead"><div class="shell"><div class="brandrow"><a class="brand brand-home" href="#overview" data-go="overview"><span class="brandmark">${icon('layers')}</span><span><strong>Feasibility Toolbox</strong><small>Rural Park & Trail Planning Toolkit</small></span></a><span class="edition">Toolbox 01 · Texas pricing, July 2026</span></div><nav class="mainnav" aria-label="Main navigation">${[['overview','Understanding Feasibility'],[lastCalculatorStep,'Cost Calculator'],['methods','Methods & Sources']].map(([id,label],i)=>go(id,'',label,`mainnav-link ${(i===0&&state.step==='overview')||(i===1&&calc)||(i===2&&state.step==='methods')?'current':''}`)).join('')}</nav></div></header>${calc?`<nav class="calculator-steps" aria-label="Cost calculator steps"><div class="shell">${[['construction','Construction'],['maintenance','Maintenance & Operations'],['lifecycle','Replacement & Lifecycle']].map(([id,label],i)=>go(id,'',`<span>${i+1}</span>${label}`,`calc-step stage-${i===2?'replacement':id} ${state.step===id?'active':''}`)).join('')}</div></nav><div class="shell"><div class="project-compact"><div><span class="sectionlabel">Your project</span><strong>${e(c.surface.name)} · ${fmt(c.A,0)} sq. ft.</strong><span class="small-note">${c.C}-year cycle · ${state.labor==='both'?'Both labor options':modeName(state.labor)}</span></div><button class="small" data-open="project-editor">Edit project</button></div><section id="project-editor" class="project-inputs-visible"><h3>Project inputs · material, size &amp; labor</h3><p class="small-note">Choose a material, then enter your trail area below. The starting example is 20,000 sq. ft. The highlighted area field is ready to edit; yellow marks values you have changed.</p><div class="surface-grid photo-selector">${Object.entries(surfaces).map(([id,s])=>`<button class="surface ${state.surface===id?'selected':''}" data-surface="${id}" aria-pressed="${state.surface===id}"><img src="assets/${id}.png" alt="${e(s.name)} reference trail" loading="lazy"><span class="surface-title">${icon(s.icon)}<strong>${e(s.name)}</strong></span></button>`).join('')}</div><div class="project-row"><div class="trail-area-callout"><div class="trail-area-copy"><span class="trail-area-kicker">Start here · Key project input</span><h4>Enter or change your trail area</h4><p>This area drives the quantities and costs in all three calculator stages.</p><div class="trail-area-impact" aria-label="Trail area affects construction, maintenance, and replacement"><span>Construction</span><span>Maintenance</span><span>Replacement</span></div></div><div class="trail-area-field">${field('area','Trail area',num(state,'length',0)>0&&num(state,'width',0)>0?num(state,'length',0)*num(state,'width',0):20000,{suffix:'sq. ft.',min:.000001,required:true})}<p>Click the number to type your project area.</p></div></div><div class="labor-control"><p class="sectionlabel">Labor options</p><div class="segmented">${[['ih','In-house'],['out','Outsourced'],['both','Show both']].map(([id,t])=>`<button data-labor="${id}" class="${state.labor===id?'selected':''}" aria-pressed="${state.labor===id}">${t}</button>`).join('')}</div><p class="small-note">In-house = your agency’s crew.<br>Outsourced = a contractor’s crew.</p></div></div>${details('size-helper','Use length and width, or enter edge length',`<div class="controls-grid">${field('length','Length (optional)',null,{suffix:'ft'})}${field('width','Width (optional)',null,{suffix:'ft'})}${field('edge','Edge length',num(state,'length',0)>0?2*num(state,'length',0):null,{suffix:'lin. ft.'})}</div><p class="small-note">Length × width supplies area; twice the length supplies edging. A direct override takes precedence until reset.</p>`)}</section></div><aside class="mini-summary" aria-label="Current project estimate"><div class="shell"><div class="mini-inner"><div><label for="summary-scenario">Summary scenario</label><select id="summary-scenario"><option value="0" ${state.summaryScenario===0?'selected':''}>1 · Maintain-and-Extend</option><option value="1" ${state.summaryScenario===1?'selected':''}>2 · Maintain + Rebuild</option></select></div>${[['construction','Construction',c.construction],['maintenance','Maintenance / year',sc.annual],['replacement','Ownership · '+c.C+' years',sc.total]].map(([cls,label,r])=>`<div class="mini-stat stage-${cls}"><span>${label}</span>${modes().map(m=>`<strong>${range(r[m],0)}</strong><small>${m==='ih'?'In-house':'Contractor'}</small>`).join('')}</div>`).join('')}</div></div></aside>`:''}`;}
function bridge(c,educational=false){return `<div class="scenario-bridge"><div class="bridge-heading"><div><p class="eyebrow">During the cycle ≠ at its end</p><h3>Two ways to plan for the same trail</h3></div><span class="tag">${e(c.surface.short)} · ${c.C} years</span></div><p class="small-note">${educational?'The example follows your current project. ':''}Both scenarios start with construction. What changes is the maintenance commitment and the amount rebuilt at the cycle’s end.</p><div class="bridge-axis"><span>Year 0 · Build</span><span>During the ${c.C}-year cycle</span><span>End of Year ${c.C}</span></div>${c.scenarios.map((sc,n)=>`<div class="bridge-row"><div class="bridge-label"><span class="scenario-index">Scenario ${n+1}</span><h4>${n===0?'Maintain-and-Extend':'Reduced Maintenance + Rebuild'}</h4></div>${educational?`<div class="scenario-example"><figure><img src="assets/${n===0?'scenario-prompt-repair':'scenario-deferred-repair'}.png" alt="${n===0?'White House exterior illustrating a prompt-repair approach':'Severely cracked road illustrating deterioration before major repair'}" loading="lazy"><figcaption>${n===0?'White House · prompt-repair example':'Damaged road · deferred-repair example'}</figcaption></figure><div><h4>${n===0?'Address problems as they arise':'Defer major repairs until deterioration reaches a threshold'}</h4><p>${n===0?'The White House image illustrates the idea of repairing damage promptly whenever it appears. Applied to a trail, regular upkeep and timely repairs help preserve its condition and extend its useful life.':'The damaged road illustrates an approach in which major repairs wait until the surface has deteriorated to a chosen threshold. Reduced upkeep can leave more extensive work to be done later.'}</p><p><strong>How this connects to Scenario ${n+1}:</strong> ${n===0?'Maintain-and-Extend budgets maintenance throughout the cycle. Under the default assumptions, the whole trail is maintained and no full rebuild is budgeted at the end of that cycle.':'Reduced Maintenance + Rebuild budgets less maintenance during use, followed by a larger renewal project. Under the default assumptions, maintenance covers 40% of the trail area and 100% is rebuilt at the end of the cycle.'}</p>${n===1?'<p class="small-note">The road image explains the strategy. The calculator schedules rebuilding at the end of the selected cycle; it does not predict when a trail reaches a damage threshold.</p>':''}</div></div>`:''}<div class="bridge-track"><div class="bridge-build stage-construction"><b>Build</b><span>Initial cost</span></div><div class="bridge-maintain stage-maintenance"><b>${fmt(sc.fraction*100,0)}% maintained</b><span>Maintenance budget during the cycle</span></div><div class="bridge-end ${sc.replaced>0?'stage-replacement':'no-rebuild'}"><b>${sc.replaced>0?fmt(sc.replaced*100,0)+'% rebuilt':'Continue use'}</b><span>${sc.replaced>0?'Remove + replace at cycle end':'No rebuild budgeted in this cycle'}</span></div></div></div>`).join('')}<div class="bridge-takeaway"><strong>Different activities. Different times.</strong><p>For Scenario 2, ${fmt(c.scenarios[1].fraction*100,0)}% describes the area used to budget maintenance during the cycle. ${fmt(c.scenarios[1].replaced*100,0)}% describes rebuilding at the end. These percentages are not added as one treatment.</p><p class="small-note">“No rebuild in this cycle” is a planning assumption—not a claim that the surface lasts forever. When Scenario 1’s maintained share is changed, its rebuilt share is 100% minus the maintained share.</p></div></div>`;}
function overview(c){return `<div class="education-intro"><div><p class="eyebrow">Understanding Feasibility</p><h2>A trail needs a plan<br>for more than opening day.</h2><p class="lede">Can your community afford to build it—and keep it usable? Explore the materials, people, maintenance, and future work behind that decision.</p><div class="actions">${go('overview','feasibility-meaning','Start with feasibility','primary-link')}${go(lastCalculatorStep,'','Go to calculator','secondary-link')}</div></div><div class="education-lenses">${[['construction','01','Construction','Build it.','A one-time investment in materials and labor.'],['maintenance','02','Maintenance','Keep it usable.','Recurring work, staff time, and a yearly budget.'],['replacement','03','Replacement','Plan for renewal.','Removal and rebuilding when the cycle ends.']].map(([cls,n,h,t,p])=>`<div class="lens-card stage-${cls}"><span>${n}</span><div><h3>${h}</h3><strong>${t}</strong><p>${p}</p></div></div>`).join('')}</div></div><nav class="education-contents" aria-label="On this page"><span>Explore</span>${[['feasibility-meaning','What is feasibility?'],['considerations','What to consider'],['materials-guide','Materials'],['why-maintenance','Maintenance'],['maintenance-replacement','Two scenarios'],['putting-together','The whole budget']].map(([id,t])=>go('overview',id,t)).join('')}</nav><section id="feasibility-meaning" class="learning-section"><div class="lesson-heading"><span class="lesson-number">01</span><div><p class="eyebrow">Think across the whole lifecycle</p><h2>What does feasibility mean?</h2></div></div><p class="lede lifecycle-definition">Feasibility means asking whether a community can support a trail throughout its life—from the initial build, through years of use and maintenance, to eventual renewal.</p><p class="lifecycle-intro">The decision connects what you build today with the money, people, and work it will need over time. A trail is feasible when those commitments fit the community’s resources across the whole lifecycle.</p><div class="feasibility-cycle" aria-label="Trail lifecycle: construction, maintenance, and replacement"><article class="stage-construction"><p class="cycle-time">At the beginning</p><h3>Construction</h3><p>Invest in the materials and labor needed to create the trail. The surface you choose also shapes future upkeep and renewal needs.</p>${go('construction','','Explore construction costs')}</article><span class="cycle-arrow" aria-hidden="true">→</span><article class="stage-maintenance"><p class="cycle-time">Throughout use</p><h3>Maintenance</h3><p>Commit staff time and a recurring budget to inspections, cleaning, repairs, and replenishment so the trail remains usable.</p>${go('maintenance','','Explore maintenance costs')}</article><span class="cycle-arrow" aria-hidden="true">→</span><article class="stage-replacement"><p class="cycle-time">When renewal is needed</p><h3>Replacement</h3><p>Plan for removal and rebuilding when routine upkeep is no longer enough. Renewal begins another period of use and maintenance.</p>${go('lifecycle','replacement-costs','Explore replacement costs')}</article></div><div class="lifecycle-conclusion"><strong>One lifecycle. A continuing commitment.</strong><p>Maintenance supports the trail during use; replacement renews it when needed. Consider both alongside construction to understand the full cost and responsibility of ownership.</p><div class="trail-condition-pair"><figure><img src="assets/trail-newly-constructed.png" alt="Illustration of a newly constructed gravel trail with a smooth surface, defined edges and clear drainage." width="1536" height="1024" loading="lazy"><figcaption><strong>Just constructed</strong><span>A smooth, even surface with clear edges and drainage.</span></figcaption></figure><figure><img src="assets/trail-without-maintenance.png" alt="Illustration of the same gravel trail without maintenance, with weeds, erosion, uneven gravel and accumulated debris." width="1536" height="1024" loading="lazy"><figcaption><strong>Without ongoing maintenance</strong><span>Weeds, erosion, and debris can make the trail uneven and harder to use.</span></figcaption></figure></div>${go('lifecycle','ownership-summary','See the whole lifecycle in the calculator')}</div></section><section id="considerations" class="learning-section"><div class="lesson-heading"><span class="lesson-number">02</span><div><p class="eyebrow">A community conversation</p><h2>What should you consider?</h2></div></div><p class="lede">Use these questions to connect a cost estimate with your local capacity. The calculator estimates costs and effort; your community judges whether those commitments are manageable.</p><div class="consideration-grid">${[['construction','Material and construction needs','What surface and layers fit the proposed trail? Confirm quantities and thicknesses against the project design.','construction','construction-layers','Explore materials in Step 1'],['construction','Initial budget and labor','Will your agency do the work, or will you hire a contractor? Check what each labor estimate includes.','construction','construction-labor','Estimate construction and labor'],['maintenance','People, equipment, and time','Who will perform the work? Consider staff availability and the equipment and skills needed.','lifecycle','staffing','View staffing estimates'],['maintenance','Recurring maintenance','What needs inspection, cleaning, repair, or surface replenishment? How often can the community support that work?','maintenance','maintenance-inputs','Explore maintenance activities'],['replacement','Service life and renewal','What cycle is being planned for, and how much of the trail will be rebuilt at its end?','lifecycle','replacement-costs','Explore replacement costs'],['replacement','Long-term affordability','Can the community support the initial investment, annual work, and eventual renewal together?','lifecycle','ownership-summary','Compare lifecycle costs']].map(([cls,h,p,step,target,l])=>`<div class="consideration-wrap stage-${cls}"><p class="consideration-stage">${cls.charAt(0).toUpperCase()+cls.slice(1)}</p><article class="consideration"><h3>${h}</h3><p>${p}</p>${go(step,target,l)}</article></div>`).join('')}</div></section><section id="materials-guide" class="learning-section"><div class="lesson-heading"><span class="lesson-number">03</span><div><p class="eyebrow">See the surface and its layers</p><h2>Understand your material choices.</h2></div></div><p class="lede">The reference photographs show what a trail can look like. The cross-sections explain the layers included in each estimate.</p><div class="material-guide-grid">${Object.entries(surfaces).map(([id,s])=>`<article class="material-guide-card">${photo(id)}<div class="material-guide-copy"><h3>${icon(s.icon)}${e(s.name)}</h3><p>${photoData[id].description}</p>${details('learn-layer-'+id,'See the construction layers',`${diagram(calculate(state,id))}<p class="small-note">${s.layers.map(k=>`${e(categories[k].name)}: ${e(categories[k].thickness)}`).join('<br>')}</p>`)}<a class="context-link" href="#construction/construction-layers" data-go="construction" data-target="construction-layers" data-use-surface="${id}">Explore ${e(s.short)} in the calculator</a></div></article>`).join('')}</div></section><section id="why-maintenance" class="learning-section"><div class="lesson-heading"><span class="lesson-number">04</span><div><p class="eyebrow">An ongoing responsibility</p><h2>Why does maintenance matter?</h2></div></div><div class="lesson-columns"><div><p>Construction happens once at the beginning. Maintenance continues while people use the trail: inspections, debris and drainage cleaning, weed control where applicable, and surface repairs.</p><p>These activities require a recurring budget and someone responsible for completing the work. The maintenance estimate helps make that commitment visible.</p><div class="teaching-equation stage-maintenance"><span>Cost of one maintenance visit</span><b>×</b><span>Number of maintenance visits per year</span><b>=</b><span>Annual maintenance cost</span></div><p class="small-note">For example, a maintenance task that costs $200 each time and is completed 6 times per year costs $1,200 per year. Add the annual costs of all tasks to find the total maintenance budget. For inspection, the cost of one visit is the per-area rate × maintained area. Surface-renewal activities use the model’s annual area-share rules, explained in Methods & Sources.</p></div><aside class="learning-note stage-maintenance"><h3>Annual and full-cycle costs are different.</h3><p><strong>Annual:</strong> one year of maintenance.</p><p><strong>Full cycle:</strong> annual maintenance × the number of years in the selected cycle.</p>${go('maintenance','','Explore annual and full-cycle maintenance')}${go('methods','maintenance-rules','Read the maintenance model rules')}</aside></div></section><section id="maintenance-replacement" class="learning-section"><div class="lesson-heading"><span class="lesson-number">05</span><div><p class="eyebrow">Connect upkeep with future work</p><h2>What happens at the end of the cycle?</h2></div></div>${bridge(c,true)}<div class="lesson-links">${go('maintenance','scenario-comparison','Compare maintenance scenarios in Step 2')}${go('lifecycle','replacement-costs','Explore end-of-cycle costs in Step 3')}</div></section><section id="putting-together" class="learning-section"><div class="lesson-heading"><span class="lesson-number">06</span><div><p class="eyebrow">Consider the whole budget</p><h2>Bring all three stages together.</h2></div></div><div class="ownership-formula"><div class="stage-construction"><b>1 · Construction</b><span>Initial materials + labor</span></div><span>+</span><div class="stage-maintenance"><b>2 · Maintenance</b><span>Work over the full cycle</span></div><span>+</span><div class="stage-replacement"><b>3 · Replacement</b><span>Removal + rebuilding, where assumed</span></div><span>=</span><div class="formula-total"><b>Ownership cost</b><span>For the selected cycle</span></div></div><div class="lesson-columns"><div><p><strong>Replacement</strong> installs the new materials and includes installation labor. <strong>Reconstruction/removal</strong> covers demolition, removal, and haul-away of the existing trail. The calculator includes both in the end-of-cycle budget.</p><p>Different surfaces have different cycle lengths. Average annual ownership divides the total by the cycle years to help compare them. It is a simple average, not a discounted financial analysis.</p></div><aside class="learning-note"><h3>Use estimates alongside local judgment.</h3><p>Confirm quantities, local quotes, staff capacity, and maintenance responsibilities before making a commitment.</p>${go('lifecycle','compare-surfaces','Compare surfaces and ownership costs')}</aside></div><div class="education-finish"><h3>Ready to explore your project?</h3><p>Use the calculator to see how trail size, material, and maintenance choices affect estimated costs.</p>${go('construction','','Explore your project costs','primary-link')}</div></section>`;}
function scenarioControls(c){return `<div class="scenario-defaults scenario-editable" aria-label="Editable lifecycle assumptions"><div class="scenario-input">${field(`${c.id}.cycle`,'Planned cycle',c.surface.cycle,{suffix:'years',min:.000001})}</div><div class="scenario-input">${field('scenario.0.maintained','Scenario 1 · maintained',100,{suffix:'%',max:100})}</div><div class="scenario-input">${field('scenario.1.maintained','Scenario 2 · maintained',40,{suffix:'%',max:100})}</div><div class="scenario-input">${field('scenario.1.rebuilt','Scenario 2 · rebuilt',100,{suffix:'%',max:100})}</div></div><p class="scenario-edit-note">Edit these assumptions directly. All maintenance and lifecycle totals update immediately. Scenario 1 rebuilt share is 100% minus its maintained share.</p>`;}
function construction(c){const old=originalConstruction(c);const start=old.indexOf('<div class="two-col">');return `${heading('Cost Calculator · Step 1','Estimate the cost to build.','Start with a surface and trail size. The budget combines the selected construction layers with your labor option.')}<div class="section-guide stage-construction"><p><strong>Construction is the initial investment.</strong> Material quantities × unit prices give the material subtotal. Labor is estimated separately for your crew or a contractor.</p>${readLink('materials-guide')}</div><div class="selected-material"><div>${photo(c.id,true)}</div><div><p class="sectionlabel">${e(c.surface.name)}</p><h3>What is included in this surface?</h3><p>${photoData[c.id].description}</p>${details('selected-cross-section','View the cross-section and layer schedule',`${diagram(c)}<p class="small-note">${c.layers.map(x=>`${e(x.name)}: ${e(x.thickness)}`).join('<br>')}</p>`)}<button class="small" data-open="project-editor">Change material or trail size</button></div></div><section class="panel stage-panel stage-construction"><div class="panel-head"><h3>Your construction estimate</h3><span class="pill">${fmt(c.A,0)} sq. ft.</span></div>${resultCards(c.construction,'Materials + labor')}<p class="small-note">Low–High is the supplied estimate range. Adjusted figures apply the editable estimate allowance.</p><p class="note">Contractor estimates come from installed-cost references and may include some materials. Materials + Outsourced is therefore a conservative upper figure.</p>${c.layers.some(l=>l.unit==='lin. ft.'&&l.quantity===0)?`<p class="note">No edging quantity is entered. Edging currently contributes $0. ${go('construction','project-editor','Enter an edge length or use the length helper')}</p>`:''}</section>${details('construction-worksheet','Customize materials, labor & construction timing',old.slice(start))}<p class="small-note">Every original input and source remains available in the detailed worksheet. Your edits follow you between steps.</p>`;}
function maintenance(c){const missing=c.scenarios[0].activities.filter(a=>a.missing);return `${heading('Cost Calculator · Step 2','Plan for the work that repeats.','Compare the recurring budget and the full-cycle commitment for two maintenance approaches.')}<div class="section-guide stage-maintenance"><p><strong>Annual maintenance is one year of work.</strong> Multiplying it by the cycle length gives the maintenance cost over the full cycle. Replacement at the cycle’s end is shown separately in Step 3.</p>${readLink('why-maintenance')}</div><section id="scenario-comparison">${bridge(c)}</section>${scenarioControls(c)}<section class="panel stage-panel stage-maintenance"><h3>Maintenance budget per year</h3><div class="two-col">${c.scenarios.map((sc,n)=>`<div><h4>Scenario ${n+1} · ${n===0?'Maintain-and-Extend':'Reduced Maintenance + Rebuild'}</h4><p class="small-note">${fmt(sc.MA,0)} sq. ft. used as the maintained area.</p>${resultCards(sc.annual,'Annual maintenance')}</div>`).join('')}</div>${details('cycle-maintenance','See maintenance totals over the full '+c.C+'-year cycle',`<div class="two-col">${c.scenarios.map((sc,n)=>`<div><h4>Scenario ${n+1} · ${c.C} years</h4>${resultCards(sc.full,'Full-cycle maintenance')}</div>`).join('')}</div>`)}</section>${missing.length?`<p class="note"><strong>Some contractor rates are unavailable and count as $0.</strong> ${missing.map(a=>e(a.name)).join('; ')}. Enter local rates in the activity details to include these costs.</p>`:''}${(c.id==='asphalt'&&!num(state,'asphalt.crack',0))||(c.id==='concrete'&&!num(state,'concrete.joint',0))?`<p class="note">${c.id==='asphalt'?'Crack':'Joint'} length is not entered, so the corresponding linear-foot costs are zero. In-house labor still follows maintained area. ${go('maintenance','maintenance-inputs','Enter activity quantities')}</p>`:''}${details('maintenance-detail','Customize activities and inspect the complete maintenance tables',`${maintenanceInputs(c)}${c.scenarios.map((sc,n)=>maintenanceTables(c,sc,n)).join('')}<section class="panel"><h3>Share of trail addressed</h3><p class="small-note">Maintenance and rebuilding occur at different times.</p><div class="bars">${c.scenarios.map((sc,n)=>[['Maintained',sc.fraction],['Rebuilt',sc.replaced]].map(([t,v])=>`<div class="bar-row"><span>S${n+1} · ${t}</span><div class="bar-track"><div class="bar ${t==='Rebuilt'?'gold':''}" style="width:${Math.max(0,Math.min(100,v*100))}%"></div></div><strong>${fmt(v*100,0)}%</strong></div>`).join('')).join('')}</div></section>${adjustments()}`)}<div class="next-context stage-replacement"><h3>Next: what happens when this cycle ends?</h3><p>Keep these maintenance costs separate from the removal and rebuilding budget.</p>${go('lifecycle','replacement-costs','Explore replacement in Step 3')}${readLink('maintenance-replacement')}</div>`;}
function stageBreakdown(c){const rows=[];c.scenarios.forEach((sc,n)=>modes().forEach(m=>{for(const [j,bound] of ['Low','High'].entries()){const parts=[c.construction[m][j],sc.full[m][j],c.replacement[m][j]*sc.replaced];rows.push({n,m,bound,parts,total:parts.reduce((a,b)=>a+b,0)});}}));const max=Math.max(1,...rows.map(r=>r.total));return `<section class="panel" id="stage-breakdown"><h3>Where does the ownership budget go?</h3><p class="small-note">Each bar is one complete estimate. Low and High are separate; the two scenarios and labor options are never added together.</p>${stageLegend()}<div class="ownership-bars">${rows.map(r=>`<div class="ownership-bar-row"><div><strong>S${r.n+1} · ${r.m==='ih'?'In-house':'Contractor'}</strong><span>${r.bound} estimate</span></div><div class="ownership-bar-track" role="img" aria-label="Scenario ${r.n+1}, ${modeName(r.m)}, ${r.bound}: construction ${money(r.parts[0])}, maintenance ${money(r.parts[1])}, replacement ${money(r.parts[2])}">${r.parts.map((v,i)=>`<span class="stage-fill-${['construction','maintenance','replacement'][i]}" style="width:${Math.max(0,v/max*100)}%" title="${['Construction','Maintenance','Replacement'][i]}: ${money(v)}"></span>`).join('')}</div><strong>${money(r.total,0)}</strong></div>`).join('')}</div><div class="table-scroll"><table><thead><tr><th>Scenario / labor</th><th class="numeric stage-construction">1 · Construction</th><th class="numeric stage-maintenance">2 · Full-cycle maintenance</th><th class="numeric stage-replacement">3 · Removal + replacement</th><th class="numeric">Ownership total</th></tr></thead><tbody>${c.scenarios.map((sc,n)=>modes().map(m=>`<tr><td>S${n+1} · ${modeName(m)}</td><td class="numeric">${range(c.construction[m])}</td><td class="numeric">${range(sc.full[m])}</td><td class="numeric">${range(c.replacement[m].map(x=>x*sc.replaced))}</td><td class="numeric">${range(sc.total[m])}</td></tr>`).join('')).join('')}</tbody></table></div></section>`;}
function lifecycle(c){return `${heading('Cost Calculator · Step 3','See the whole cost of ownership.','Combine the initial build, maintenance over the cycle, and any removal and replacement at its end.')}<div class="section-guide stage-replacement"><p><strong>Replacement installs the new trail layers.</strong> Removal and haul-away deal with the existing trail. These costs are multiplied by the scenario’s rebuilt share before they enter the total.</p>${readLink('maintenance-replacement')}</div>${scenarioControls(c)}<section class="panel stage-panel stage-replacement" id="replacement-introduction"><h3>Full replacement + removal</h3><p class="small-note">This is the budget for rebuilding 100% of the entered quantities. The actual share charged is ${fmt(c.scenarios[0].replaced*100,0)}% in Scenario 1 and ${fmt(c.scenarios[1].replaced*100,0)}% in Scenario 2.</p>${resultCards(c.replacement,'Full rebuild + removal')}${details('replacement-detail','Customize replacement quantities and removal costs',replacement(c))}</section><section class="panel" id="ownership-summary"><h3>Full-cycle ownership · ${c.C} years</h3><div class="two-col">${c.scenarios.map((sc,n)=>`<div><h4>Scenario ${n+1} · ${n===0?'Maintain-and-Extend':'Reduced Maintenance + Rebuild'}</h4>${resultCards(sc.total,'Full-cycle ownership')}<div class="annual-ownership">${modes().map(m=>`<div class="statline"><span>${m==='ih'?'In-house':'Contractor'} / year</span><strong>${range(sc.perYear[m])}</strong></div>`).join('')}</div></div>`).join('')}</div><p class="small-note">Average annual ownership = total ÷ cycle years. It includes all three stages and is different from annual maintenance alone.</p>${readLink('putting-together')}</section>${stageBreakdown(c)}${details('ownership-components','Inspect every lifecycle cost component',ownershipTable(c))}${compareAll()}${staffing(c)}${adjustments()}<div class="next-context"><h3>Use the estimate in your feasibility discussion.</h3><p>Consider the budget alongside local staffing, equipment, maintenance responsibilities, and project-specific quotes.</p>${go('overview','considerations','Return to the feasibility considerations')}</div>`;}
function showPhoto(id){if(!photoData[id])return;let dialog=document.querySelector('#material-photo-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='material-photo-dialog';document.body.append(dialog);}dialog.innerHTML=`<div class="photo-dialog-head"><h3>${e(photoData[id].caption)}</h3><button data-close-photo aria-label="Close reference photograph">Close</button></div><img src="assets/${id}.png" alt="${e(photoData[id].caption)} reference photograph">`;dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.showModal();}
function revealTarget(target){let el=document.getElementById(target)||[...document.querySelectorAll('details')].find(d=>d.dataset.panel===target);if(!el)return false;let p=el;while(p){if(p.tagName==='DETAILS')p.open=true;p=p.parentElement;}el.setAttribute('tabindex','-1');el.scrollIntoView({behavior:'smooth',block:'start'});el.focus({preventScroll:true});return true;}
app.addEventListener('click',ev=>{const link=ev.target.closest('a[data-go]');if(link){ev.preventDefault();if(link.dataset.useSurface)state.surface=link.dataset.useSurface;navigate(link.dataset.go,link.dataset.target||'');return;}const button=ev.target.closest('button');if(button?.dataset.open){revealTarget(button.dataset.open);return;}if(button?.dataset.photo)showPhoto(button.dataset.photo);});
window.addEventListener('popstate',()=>{const [step,target]=location.hash.slice(1).split('/');navigate(step||'overview',target||'',false);});

app.addEventListener('click',ev=>{const b=ev.target.closest('button[data-delete-maintenance-labor]');if(!b)return;try{deleteCustomerMaintenanceLaborOption(state,b.dataset.deleteMaintenanceLabor,b.dataset.activity,b.dataset.mode,Number(b.dataset.index));registry.clear();render();validate();render();notify('Maintenance labor option deleted. Annual and lifecycle totals have been updated.');}catch(error){notify(error.message);}});
app.addEventListener('submit',ev=>{const form=ev.target.closest('form[data-add-maintenance-labor]');if(!form)return;ev.preventDefault();if(!form.reportValidity())return;try{addCustomerMaintenanceLaborOption(state,form.dataset.addMaintenanceLabor,form.dataset.activity,Object.fromEntries(new FormData(form)));validate();render();notify('Maintenance labor option added and selected. Annual and lifecycle totals now use its calculated rate.');}catch(error){form.querySelector('.product-form-error').textContent=error.message;}});
app.addEventListener('change',ev=>{const t=ev.target;if(!t.dataset.maintenanceLaborSelect)return;try{selectMaintenanceLaborOption(state,t.dataset.maintenanceLaborSelect,t.dataset.activity,t.dataset.mode,t.dataset.index==='default'?'default':Number(t.dataset.index));validate();render();notify('Maintenance labor option updated.');}catch(error){notify(error.message);}});
app.addEventListener('click',ev=>{const b=ev.target.closest('button[data-delete-labor]');if(!b)return;try{deleteCustomerLaborOption(state,b.dataset.deleteLabor,b.dataset.mode,Number(b.dataset.index));registry.clear();render();validate();render();notify('Labor option deleted. The selected rate has been updated.');}catch(error){notify(error.message);}});
app.addEventListener('submit',ev=>{const form=ev.target.closest('form[data-add-labor]');if(!form)return;ev.preventDefault();if(!form.reportValidity())return;try{addCustomerLaborOption(state,form.dataset.addLabor,Object.fromEntries(new FormData(form)));validate();render();notify('Labor option added and selected. Construction and lifecycle estimates now use its calculated rate.');}catch(error){form.querySelector('.product-form-error').textContent=error.message;}});
app.addEventListener('change',ev=>{const t=ev.target;if(!t.dataset.laborSelect)return;try{selectLaborOption(state,t.dataset.laborSelect,t.dataset.mode,t.dataset.index==='default'?'default':Number(t.dataset.index));validate();render();notify('Construction labor option updated.');}catch(error){notify(error.message);}});
app.addEventListener('click',ev=>{const b=ev.target.closest('button[data-delete-product]');if(!b)return;try{const result=deleteCustomerProduct(state,b.dataset.deleteProduct,Number(b.dataset.index));registry.clear();render();validate();render();notify(result.fallback?'Product deleted. Example products are selected because no selected products remain.':'Product deleted. Selected average recalculated.');}catch(error){notify(error.message);}});
app.addEventListener('submit',ev=>{const form=ev.target.closest('form[data-add-product]');if(!form)return;ev.preventDefault();if(!form.reportValidity())return;try{addCustomerProduct(state,form.dataset.addProduct,Object.fromEntries(new FormData(form)));validate();render();notify('Product added and selected. Estimates now use its price.');}catch(error){form.querySelector('.product-form-error').textContent=error.message;}});
app.addEventListener('change',ev=>{const t=ev.target;if(!t.dataset.productSelect)return;try{selectProduct(state,t.dataset.productSelect,Number(t.dataset.index),t.checked);validate();render();notify('Selected product average updated.');}catch(error){t.checked=true;notify(error.message);}});
app.addEventListener('input',ev=>{const t=ev.target;if(!(t instanceof HTMLInputElement)||!t.dataset.key)return;state.overrides[t.dataset.key]=t.value;validate();refreshKeepingFocus(t);});
app.addEventListener('change',ev=>{const t=ev.target;if(t.id==='summary-scenario'){state.summaryScenario=Number(t.value);render();}else if(t.id==='compare-metric'||t.id==='compare-scenario'){state.overrides[t.id==='compare-metric'?'compare.metric':'compare.scenario']=t.value;render();}});
app.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.step){navigate(b.dataset.step);return;}if(b.dataset.surface){state.surface=b.dataset.surface;render();return;}if(b.dataset.labor){state.labor=b.dataset.labor;render();return;}if(b.dataset.reset){delete state.overrides[b.dataset.reset];validate();render();return;}const a=b.dataset.action;if(a==='reset-all'){const {step,surface,labor}=state;state=initialState();Object.assign(state,{step,surface,labor});invalidKeys.clear();render();notify('All prices, quantities, and assumptions reset to defaults.');}if(invalidKeys.size)return;if(a==='csv'){const blob=new Blob(['\ufeff'+toCSV(exportRows(state))],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Trail_Feasibility_Results.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('CSV exported for all five surfaces and both scenarios.');}if(a==='copy'){const text=summaryText();try{await navigator.clipboard.writeText(text);notify('Project summary copied.');}catch{let area=document.querySelector('#copy-fallback');if(!area){const box=document.createElement('section');box.className='panel';box.innerHTML='<h3>Copy your summary</h3><p>Select and copy the text below.</p><textarea id="copy-fallback" class="copy-fallback" readonly aria-label="Shareable project summary"></textarea>';document.querySelector('#main').append(box);area=box.querySelector('textarea');}area.value=text;area.focus();area.select();area.scrollIntoView({behavior:'smooth'});}}if(a==='print'){printing=true;render();requestAnimationFrame(()=>window.print());}});
window.addEventListener('afterprint',()=>{if(printing){printing=false;render();}});
render();
if(typeof location!=='undefined'&&location.hash){const [firstStep,firstTarget]=location.hash.slice(1).split('/');navigate(firstStep,firstTarget||'',false);}
// Page-scoped agent tools use the exact same state and calculations as the interface.
const context=document.modelContext;
if(context?.registerTool){const lifecycleController=new AbortController();const tools=[{name:'read_trail_estimate',title:'Read trail estimate',description:'Read the current project and both lifecycle scenarios without changing inputs.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){if(invalidKeys.size)throw new Error('Correct invalid project inputs first.');const c=calculate(state);return {surface:state.surface,area:c.A,cycle:c.C,construction:c.construction,scenarios:c.scenarios.map(sc=>({maintained:sc.fraction,rebuilt:sc.replaced,annualMaintenance:sc.annual,total:sc.total,perYear:sc.perYear}))};}},{name:'configure_trail_project',title:'Configure trail project',description:'Change trail surface, area, and scenario fractions on this page, then recalculate the visible estimate.',inputSchema:{type:'object',properties:{surface:{type:'string',enum:Object.keys(surfaces)},area:{type:'number',exclusiveMinimum:0},scenario1MaintainedPercent:{type:'number',minimum:0,maximum:100},scenario2MaintainedPercent:{type:'number',minimum:0,maximum:100},scenario2RebuiltPercent:{type:'number',minimum:0,maximum:100}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input))throw new Error('Expected a project object.');const keys=['surface','area','scenario1MaintainedPercent','scenario2MaintainedPercent','scenario2RebuiltPercent'];for(const [key,v] of Object.entries(input)){if(!keys.includes(key))throw new Error('Unknown project field.');if(key==='surface'){if(!Object.hasOwn(surfaces,v))throw new Error('Unknown trail surface.');}else if(typeof v!=='number'||!Number.isFinite(v)||(key==='area'?v<=0:v<0||v>100))throw new Error('Invalid quantity or percentage.');}if(input.surface)state.surface=input.surface;const map={area:'area',scenario1MaintainedPercent:'scenario.0.maintained',scenario2MaintainedPercent:'scenario.1.maintained',scenario2RebuiltPercent:'scenario.1.rebuilt'};for(const [k,path] of Object.entries(map))if(input[k]!==undefined)state.overrides[path]=input[k];state.step='construction';validate();render();return {surface:state.surface,area:area(state),summary:summaryText()};}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycleController.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycleController.abort(),{once:true});}
